window.harnessChunks["rows-e9c2cbffb1a43585.js"]=["<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-18T21:20:13+03:00\"><th scope=\"row\"><a href=\"https://github.com/neosigmaai/auto-harness\" target=\"_blank\" rel=\"noopener\">Auto Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/neosigmaai/auto-harness/tree/52360dbbeb8cea8886d90778e634a145c51da735\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 52360dbbeb8cea8886d90778e634a145c51da735\">52360db &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A. - Function: autonomously transform the target agent harness through repeated diagnose-change-evaluate-keep/revert cycles. - Disturbance / variety regulated: benchmark failures, trace evidence, regression risk and alternative harness-improvement hypotheses. - Decisive decision or feedback right: the coding agent selects diagnoses and harness changes and decides the next hypothesis based on gate results within the supplied program. - Decision owner: autonomous coding-agent actor executing the first-party program. - Supporting / enforcement mechanisms: benchmark runners, file guard, regression suite, held-out/full-test gate, results ledger and learnings file. - Closure path: successful changes are committed and become the next harness baseline; failed changes are reverted and the next iteration consumes the recorded outcome. - Basis /\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: —. - The reviewed optimization loop has one primary coding-agent work cell. Benchmark tasks and runner concurrency are evaluation workload, not multiple organizational S1 units with a mutual-interference regulation loop. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: —. - Gating, stop conditions, configuration and benchmark execution constrain the primary optimization operation. No distinct first-party actor is established with a current whole-system view and discretionary authority over shared organizational resources, priorities or commitments. - Runtime enforcement is not promoted to S3 ownership. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: —. - Regression and held-out/full-test evaluation are the ordinary acceptance path of the optimization operation. They are intentionally protected against train-trace leakage, but the pinned system does not establish a separate complementary auditor with independent access and a corrective feedback channel beyond that normal production gate. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: —. - The system learns from benchmark failures and updates the harness, but this is internal task-distribution optimization. No externally and prospectively oriented environment model generates adaptation options and closes them back into current organizational capability. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: —. - Humans choose the benchmark/configuration and can edit the program, but the reviewed distribution does not provide a runtime identity/ultimate-policy issue → parent decision → return-to-operation loop. -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/96a771605cae253b024233012a564fafde18c029/assessments/auto-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 96a771605cae253b024233012a564fafde18c029\">96a7716 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-16T16:48:15+03:00\"><th scope=\"row\"><a href=\"https://github.com/urbanbreach/agent-harness\" target=\"_blank\" rel=\"noopener\">urbanbreach Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-16\">2026-10-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/urbanbreach/agent-harness/tree/5d2a15952ee86ea6cc3dfa8bc265b13f78c7d0a4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5d2a15952ee86ea6cc3dfa8bc265b13f78c7d0a4\">5d2a159 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: execute one coding/inspection task through model-selected tool actions and observation-dependent continuation. - Disturbance / variety regulated: unknown file/project state, command results, errors and changing requirements within the operator&#39;s task. - Decisive decision or feedback right: choose the next file/tool/shell action from the evolving prompt/observations or stop with an answer. - Decision owner: model-driven coding-agent actor in the first-party turn worker; external API supplies model computation, not an external prebuilt coding-agent harness. - Supporting / enforcement mechanisms: Runtime::queueturn, provider request, registry, execution semaphore, permissions, tool result journal, session context and optional subagents. - Closure path: user turn → provider response with calls → permission/dispatch → runtools → aftertools → updateprompt → another providerresponse or final answer. - Boundary reachability: crates/harness-core/src/coord/turn/worker.rs executes this loop as the normal turn-worker path, not in examples, CI or an imported third-party coding agent. Standard CLI/TUI users enter the coordinator and can enable installed tool registry. - Why this is / is not agent-owned: nontrivial next-action selection comes from a model rather than a fixed tool script. The coordinator&#39;s limits and human allow/deny permissions constrain execution but do not prescribe the full action sequence. - Evidence: coord/turn/worker.rs, coord/turn.rs, coord/tools/execution.rs. - Basis: explicit. - Confidence: high for code-path existence; runtime inference not independently executed. - Caveats: tool access and final coding quality depend on permissions, environment and provider availability.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no S2-specific inter-S1 conflict attenuation loop is established at the local session recursion. - Disturbance / variety regulated: concurrent tool use, waiting tasks, subagent scheduling and potential workspace conflicts; these do not alone show specific interference between separate operational S1 units. - Decisive decision or feedback right: adjudicate inter-S1 interference and return a coordination judgment altering subsequent S1 work. - Decision owner: none evidenced for an S2-specific relation; session coordinator applies scheduling and tool-level constraints while the parent chooses subagent work. - Supporting / enforcement mechanisms: children lifecycle, tools semaphore, task queue, journal and subagent outputs. - Closure path: tools and children complete and return observations, but that general work routing is not independently established as conflict-specific S2 attenuation. - Why this is / is not agent-owned: delegating to workers and limiting capacity are not an evidenced oscillation/collision regulation relation across distinct S1s. - Evidence: coord/children.rs, coord/tools/execution.rs, crates/harness-tools/src/subagents.rs. - Basis: structural, bounded negative. - Confidence: medium. - Caveats: an externally configured multi-agent workflow may supply interference mediation beyond the evidence of this frozen standard operation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no global current-control function governing a whole operational S1 portfolio at this session boundary is established. - Disturbance / variety regulated: active-turn cancellation, permission violations, tool capacity, context-length pressure and prompt steering. - Decisive decision or feedback right: reallocate shared S1 priorities/resources/commitments on a whole-system current view, with returned intervention. - Decision owner: first-party fixed constraints and operator inputs control local session execution; no independent S3 discretionary owner is evidenced. - Supporting / enforcement mechanisms: coordinator task queue, steering, lifecycle management, max iterations, cancellation, permission grant and session status. - Closure path: local operations can be paused, denied, steered or ended; no separately evidenced whole-system current view → current-control decision → returned cross-S1 change. - Why this is / is not agent-owned: scheduling, quotas and permission interrupts do not establish S3 simply because a coordinator owns them. - Evidence: coord/turn.rs, coord/lifecycle.rs, coord/permissions.rs. - Basis: structural, bounded negative. - Confidence: medium. - Caveats: human management across multiple sessions or repositories is outside this included single-session recursion.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: distinct source-inspecting review children are supported in the standard interface, but their independence and corrective return at the declared runtime boundary have not been established with sufficient source coverage for S3. - Disturbance / variety regulated: incorrect code changes, unsafe tool use or inadequate subagent deliverables. - Decisive decision or feedback right: independently assess operational evidence through a complementary path, return a finding that drives correction. - Decision owner: possible model-driven reviewer child, dispatched by the parent; not verified as an independent corrective authority in the shipped first-party wiring. - Supporting / enforcement mechanisms: named reviewer/security-reviewer subagents, optional child execution, shared event journal and parent-facing child outputs. - Closure path: a reviewer may return messages, but the necessary complementary access/independence and correction-to-operation path remain unresolved. General model self-checks and CI are not a substitute. - Why this is / is not agent-owned: a distinct child role could make an independent judgment, but a label and delegation alone do not prove an operationally complementary auditor or corrective closure. - Evidence: README, coord/publicsubagents.rs, crates/harness-tools/src/subagents.rs. - Basis: explicit availability of child roles, unknown function-specific closure. - Confidence: low. - Caveats: no distinct operational auditor trace or configured enforcement of independent reviewer ownership was tested.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party prospective environmental intelligence/adaptation loop is established. - Disturbance / variety regulated: changing model abilities, project conventions, tool ecosystem and prospective workflows. - Decisive decision or feedback right: judge future adaptation options based on external sensing, then return a changed capability/commitment into present operations. - Decision owner: operator selects models/skills/configuration and project maintainers evolve releases; no first-party S4 owner/closure evidenced. - Supporting / enforcement mechanisms: provider catalog, plug-in tools, user skills, configurable profiles, compaction, session fork/replay and hooks. - Closure path: static configuration/skills can affect a subsequent turn, but no demonstrated external future-oriented detection → organizational adaptation choice → returned capability change. - Why this is / is not agent-owned: tooling extensibility and response to current tool feedback belong to S1/local control, not necessarily S4. - Evidence: README, config.rs, providercatalog.rs. - Basis: structural, bounded negative. - Confidence: medium. - Caveats: user-authored adaptation workflows are not first-party closed S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no ultimate-policy/organizational identity adjudication loop is established for a local coding session. - Disturbance / variety regulated: prohibited shell commands, out-of-workspace paths, user-approved permission exceptions and selected safety modes. - Decisive decision or feedback right: resolve conflicting fundamental purposes/authority and return a binding ultimate-policy decision affecting the current organization. - Decision owner: user/operator supplies permission rules and approvals; fixed engine enforces these rules. No supported identity-level governance decision loop with returned authorization is established. - Supporting / enforcement mechanisms: permission policy allow/ask/deny and timeout, local config, prompt instructions, user steering and human CLI gate. - Closure path: tool request → local policy evaluation → optional operator allow/deny → tool execution/denial. This is local permission enforcement, not a returned ultimate-policy decision over system identity. - Why this is / is not agent-owned: prompt rules and operator gate ownership do not create first-party S5 decisional authority or the specific parent-mode closure required for P. - Evidence: coord/permissions.rs, config/permissions.rs, README. - Basis: structural, bounded negative. - Confidence: medium-high. - Caveats: legitimate host organization can formulate broader policy externally, but is not included in this session.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f51316e65d1d54b1aad66b8506ff12580f6c63fe/assessments/urbanbreach-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f51316e65d1d54b1aad66b8506ff12580f6c63fe\">f51316e &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-22T00:59:57+03:00\"><th scope=\"row\"><a href=\"https://github.com/xincode-ai/xin-code\" target=\"_blank\" rel=\"noopener\">Xin Code</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-22\">2026-10-22</time></td><td class=\"review-ref\"><a href=\"https://github.com/xincode-ai/xin-code/tree/c5a7969309f7286d1f513caf0821256d4036f4d7\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision c5a7969309f7286d1f513caf0821256d4036f4d7\">c5a7969 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Model-guided coding actions and result-responsive tool execution. - Disturbance / variety regulated: Varying user coding instructions, files, tool failures, and outcomes. - Decisive decision or feedback right: Model-generated choice of a next tool or response after observing tool output. - Decision owner: Xin Code main agent/model loop; tool executor performs chosen effects, with human permission when configured. - Supporting / enforcement mechanisms: Provider adapter, registry, permission checker, result compaction and session persistence. - Closure path: Prompt → model request → tool calls → tool execution → result messages → next model request; history is saved. - Boundary reachability: Shipped main.go registers first-party tools and instantiates Agent.Run; no custom external harness required. - Why this is / is not agent-owned: Without the model-owned next-tool judgment, the first-party host is a command UI, not the coding S1. - Evidence: agent.go; main.go; internal/tool/executor.go; internal/tool/builtin/register.go - Basis: explicit and structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No established inter-S1 interference attenuation/return for separate viable operational units. - Disturbance / variety regulated: Potential contention between spawned child agents for filesystem/tools, user attention or limited resources. - Decisive decision or feedback right: A qualifying S2 decision would handle observed competition between distinct S1 units and return an attenuating action to them. - Decision owner: No decisive S2 owner established; parent agent may delegate work and the executor serializes tool effects. - Supporting / enforcement mechanisms: Synchronous child-agent tool and registry; permission dialog; read-only tool batching. - Closure path: Child Agent returns one result synchronously to parent, while SendMessage explicitly rejects asynchronous child messaging; no sibling-conflict feedback to separate S1s. - Boundary reachability: No positive S2 boundary reachability established. - Why this is / is not agent-owned: Spawning child models or serializing one turn&#39;s mutating tools is not inter-S1 homeostasis. - Evidence: internal/tool/builtin/agenttool.go; internal/tool/builtin/sendmsgtool.go; internal/tool/executor.go; internal/agent/registry.go - Basis: structural bounded negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No installed whole-system current-control decision over a portfolio of S1 operations and shared commitments. - Disturbance / variety regulated: Current task states, costs, retries, sessions, resource use and failures. - Decisive decision or feedback right: A qualifying current-control owner would decide global priorities/resources/commitments in response to a whole-system view. - Decision owner: No such distinct owner shown; the operator configures budgets/modes, while the model manages a single user task. - Supporting / enforcement mechanisms: TaskStore, cost tracker, MaxTurns, active run mutex, permission checks, session view. - Closure path: Task create/update/list and cost reporting support task-local execution but do not form a whole-current supervisory intervention returned to multiple independent operations. - Boundary reachability: No positive whole-current management path credited. - Why this is / is not agent-owned: Static limits and task records are not current-control authority; per-task model planning cannot be counted as a global manager. - Evidence: internal/tool/builtin/task.go; config.go; main.go; agent.go; internal/cost/tracker.go - Basis: structural bounded negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No separate complementary and sufficiently independent operational auditing of an S3 management account. - Disturbance / variety regulated: Coding errors, misreported outcomes, unsafe tool results, and QA requests. - Decisive decision or feedback right: An independently sourced audit judgment that changes accountable current management. - Decision owner: No installed audit judgment owner; /review just prompts the ordinary main agent for a git diff review. - Supporting / enforcement mechanisms: Slash review prompt, tool outputs, hooks and local permission checks. - Closure path: A model may review code on request, but no independent S3 reporting challenge or authorized corrective return to current management is wired. - Boundary reachability: No positive S3 audit path credited. - Why this is / is not agent-owned: Review of task code and deterministic hook/permission gates do not establish an independent complementary channel. - Evidence: internal/slash/handler.go; internal/hooks/hooks.go; internal/tool/executor.go; main.go - Basis: structural bounded negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No shipped prospective adaptation decision and durable adoption into future agent capability. - Disturbance / variety regulated: Changing external coding constraints, project conditions, tool/model options and task outcomes. - Decisive decision or feedback right: A qualified S4 owner would compare prospective alternatives, choose and install a new operating capability or arrangement for later tasks. - Decision owner: Not established; human chooses model/settings/plugins and developers ship software changes. - Supporting / enforcement mechanisms: Session resume, local context compaction, user-provided skills/plugins, retry and model config. - Closure path: Past messages can inform another step and user edits may change configuration, but no source-wired meta-adaptation promotion from observations into subsequent runtime strategy/capability is identified. - Boundary reachability: No positive S4 adaptation path credited. - Why this is / is not agent-owned: Context compaction, installing third-party plugins and developer roadmaps are not an autonomous organizational future-intelligence loop. - Evidence: internal/session/compact.go; internal/plugins/plugins.go; internal/skills/skills.go; config.go; internal/agent/retry.go - Basis: structural bounded negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No runtime organization-level ultimate-purpose or identity authority closing back into operation. - Disturbance / variety regulated: User prompts, project instructions, credentials and permission policies. - Decisive decision or feedback right: A qualified S5 owner would adjudicate ultimate system purpose/identity, then return a binding decision to the harness. - Decision owner: Operator supplies project directives, APIs, models and permission mode; harness enforces chosen limits. - Supporting / enforcement mechanisms: XINCODE.md, settings, SimplePermissionChecker, request/approval TUI and CLI. - Closure path: Policy checks govern effects of individual tools and model context, but no distinct ultimate-policy issue → legitimate authority → authoritative return path is installed. - Boundary reachability: No positive S5 mode credited, including no function-specific parent-closed loop. - Why this is / is not agent-owned: Static prompts, tool approvals and installation settings represent external task bounds and execution controls, not first-party S5 ownership. - Evidence: internal/tool/permission.go; config.go; internal/context/claudemd.go; main.go; agent.go - Basis: structural bounded negative -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/8813a612b5f312385a40f6abf56e6102cf63f197/assessments/xi/xin-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 8813a612b5f312385a40f6abf56e6102cf63f197\">8813a61 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-18T21:20:13+03:00\"><th scope=\"row\"><a href=\"https://github.com/thirdlayerinc/autoagent\" target=\"_blank\" rel=\"noopener\">AutoAgent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/thirdlayerinc/autoagent/tree/eb3f185dc9faac276955b4fe5feb93c8f836b644\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision eb3f185dc9faac276955b4fe5feb93c8f836b644\">eb3f185 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A. - Function: repeatedly diagnose benchmark failures and transform the target harness toward higher pass count or equivalent performance with lower complexity. - Disturbance / variety regulated: task failures, verifier mismatches, missing capabilities/tools, orchestration alternatives and regressions across experiment variants. - Decisive decision or feedback right: the meta-agent groups failure causes, selects a general harness hypothesis, edits the harness and decides the next experiment subject to the first-party keep/discard contract. - Decision owner: autonomous meta-agent actor executing program.md. - Supporting / enforcement mechanisms: Harbor task runs, verifier scores, Git commits/reverts, results ledger, Docker isolation and the fixed adapter boundary. - Closure path: kept changes become the next harness baseline; discarded runs still feed task-level failure evidence into the next hypothesis. - Basis /\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: —. - The baseline agent.py exposes one primary autonomous task agent, and the meta-agent may later choose to add handoffs/subagents. Generic ability to construct multi-agent topologies does not establish a supplied disturbance-specific coordination function at this pinned boundary. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: —. - Experiment scoring, simplicity tie-breaking and keep/discard decisions are part of the primary harness-search operation. They do not establish a separate current-whole regulator over shared operational resources, priorities or commitments. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: —. - Harbor verifiers and benchmark scores are the normal production/evaluation feedback by which this optimization operation defines success. The reviewed distribution does not supply an additional sufficiently independent audit path that challenges ordinary operational reporting and then returns corrective findings into a separate current-control loop. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: —. - Learning from benchmark failures and evolving prompts/tools/orchestration is self-improvement of the primary operation. No externally and prospectively oriented environmental model is established that develops future adaptation options and closes them into present organizational capability. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: —. - The human authors program.md and may change the directive/model constraint, but this is developer/parent configuration. No first-party runtime path is shown where an identity/ultimate-policy issue reaches legitimate parent authority and the returned decision governs subsequent operation as an S5 loop. -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/96a771605cae253b024233012a564fafde18c029/assessments/autoagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 96a771605cae253b024233012a564fafde18c029\">96a7716 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-17T23:47:24+03:00\"><th scope=\"row\"><a href=\"https://github.com/w8123/EnterpriseAgentFramework\" target=\"_blank\" rel=\"noopener\">ReachAI / EnterpriseAgentFramework</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-17\">2026-10-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/w8123/EnterpriseAgentFramework/tree/44bc68d3670709b4b6ab490af8a699f8934aab38\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 44bc68d3670709b4b6ab490af8a699f8934aab38\">44bc68d &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Deliver enterprise-user outcomes through model-directed planning, selection of authorized Workflow-as-Tool and iterative response to actual tool/environment feedback. - Disturbance / variety regulated: Variable user intent, external business-service results/errors, workflow outcomes, permission refusal and unanticipated needs for replan. - Decisive decision or feedback right: The configured model-backed Supervisor chooses plan, eligible tool calls or revised path using returned ToolResultBlock / observation. - Decision owner: Configured AgentScope ReAct model actor within the first-party assembled ReachAI Supervisor, not the external inference provider organization; deterministic GraphSpec executor and policy are supporting mechanisms. - Supporting / enforcement mechanisms: Published immutable Agent/Workflow snapshots, tool allowlist, identity resolution, policy guard, human one-time approval, GraphSpec kernel, trace/state and workflow conversation memory. - Closure path: User request → first-party Active Agent snapshot → ReAct plan/tool choice → first-party policy allow/confirm/deny → pinned GraphSpec workflow or approved external capability → tool result/error returned to ReAct → continuing plan/replan or final answer/trace. - Boundary reachability: Ordinary RuntimeAgentExecutionService.executeResolvedContext invokes SupervisorRuntimeAdapter; the shipped AgentScopeSupervisorRuntimeAdapter builds ReActAgent/Toolkit and executes workflow tools through actual policy and GraphSpec. No example-only agent or unrelated provider internals are credited. - Why this is / is not agent-owned: Model-selected plan and tool decisions respond to runtime observations; declarative steps and hard permission enforcement are not autonomous decisions. - Evidence: enter; agent; agent; agent; agent; policy; graph. - Basis: Explicit first-party source control flow. - Confidence: High for reachable supported source path, not an executed live business/LLM test. - Caveats: Real effects require configured model, enterprise integrations and published tools; no claim about model quality or externally hosted applications.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No shipped S2-specific inter-independent-S1 interference attenuation and returned mutual adjustment was established at this app recursion. - Disturbance / variety regulated: Potential concurrent reads, duplicate side effects, tool collisions and different worker/workflow demands; reviewed gates regulate one execution plan and unsafe task operations rather than opposing independent S1 goals. - Decisive decision or feedback right: The configured Supervisor decides which planned Workflow tool to invoke; deterministic reservations and read-only parallel flag enforce task safety but do not choose a dynamic response to inter-S1 oscillation. - Decision owner: Task-local model actor, runtime admission/policy gates and user confirmation; no distinct verified S2-specific adjustment owner. - Supporting / enforcement mechanisms: Toolkit parallel-read-only configuration, single-run planning reservations, duplicate workflow-call prevention, risk permissions and workflow state. - Closure path: Per-run planned calls reserve/execute or fail; there is no demonstrated identification of a concrete clash of independent operating S1 units followed by attenuation and returned change of their behavior. - Why this is / is not agent-owned: Parallel-read-only restrictions and routing are safety constraints/task scheduling, not evidenced inter-unit coordination decisions. - Evidence: agent; agent; agent; policy. - Basis: Explicit per-execution constraints and examined app-level boundary, bounded negative. - Confidence: Medium-high in installed first-party standard paths. - Caveats: A deployment can compose a multi-workstream coordinator externally; no such S2 loop may be borrowed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No established cross-operational current-control decision loop, despite administrative monitoring, workflow runtime and agent controls. - Disturbance / variety regulated: Concurrent business projects, agent workloads and runtime failures could compete for shared commitments/capacity, but examined native surfaces operate per Agent/run or summarize them without a single governing cross-workload decision-return owner. - Decisive decision or feedback right: Current Supervisor selects tools and replans one user task; administrator may publish/change Agent config; neither source path ties whole-current RunOps aggregate view to a direct resource/commitment/priority bargaining judgment affecting multiple S1 units. - Decision owner: Task model, deterministic guard/execution services and external administrator; no demonstrated first-party whole-current S3 right or parent-governed returned decision at this recursion. - Supporting / enforcement mechanisms: RunOps diagnostics and trace views, automation target execution, fixed published version/configuration, ACL and per-task planner. - Closure path: RunOps provides operating records and administrators can separately modify configuration; missing witnessed loop is cross-S1 current situation → resource/commitment arbitration → binding returned interventions into S1. - Why this is / is not agent-owned: The word Supervisor, dashboards and publish APIs do not establish whole-organization current-control judgment; static caps and monitoring are separate from ownership. - Evidence: ops; ops; agent; attach; enter. - Basis: Inspected active operating paths and distinct administrative APIs, bounded negative. - Confidence: Medium; operator deployment can layer S3 but no app-owned integrated whole-current loop established. - Caveats: Does not claim that humans running an enterprise deployment cannot provide actual S3 outside the packaged runtime.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: Plausible but unresolved independent complementary challenge of operating claims via first-party RunOps and separately chosen EvalOps datasets. - Disturbance / variety regulated: Unreliable agent/workflow success claims, regression and unexpected guard/side-effect conditions. - Decisive decision or feedback right: EvalOps worker separately evaluates frozen Agent/version candidates against versioned datasets, scores and stores gate pass/fail; whether this independently audits ordinary operating evidence and returns an actionable finding into current-control/report correction is not established. - Decision owner: External selected evaluation dataset/test designer and deterministic EvalOps evaluator/gate; no evidenced S3-specific independent model/controller judgment with corrective operating return. - Supporting / enforcement mechanisms: RunOps per-run trace/guard facts; experiment baseline/candidate snapshots, dataset items, deterministic judge, persisted results and gateStatus. - Closure path: Selected eval experiment → isolated evaluation tasks → deterministic scoring/regression gate result; identified missing/unclear link is audit finding that amends or withholds ordinary S1–S3 operating claims and changes live control. - Why this is / is not agent-owned: An independent comparison and a gate status are real, but the current evidence does not show ownership and corrective return required for S3. Neither assert positive nor erase this material shipped candidate with a definitive absence grade. - Evidence: ops; ops; evalrun; eval; eval; policy. - Basis: Explicit installed independent evaluation facility and separate gate output; missing function-specific corrective-return evidence. - Confidence: Low for S3 classification; moderate for real evaluator path. - Caveats: Unknown whether an additional product-owned publish/feedback consumer ties a FAILED gate to accountable corrective control. Do not confuse routine permission Guard with independent audit.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: A specific prospective capability-adaptation candidate exists, but its selection, parent authority and effective return into installed operation are not yet fully reconstructed. - Disturbance / variety regulated: Changing enterprise work patterns, successful production routes not yet exposed as reusable Workflow capability, future provider/workflow quality. - Decisive decision or feedback right: A selected successful RunOps trace can trigger AI Coding draft generation and source-checked read-only GraphSpec validation; legitimate developer/operator separately accepts, publishes and attaches; unclear whether this is one supported function-specific adaptation decision loop or merely independently operable artifacts. - Decision owner: Operator initiates trace candidate; external AI Coding worker proposes; first-party services validate/store DRAFT; operator/administrator explicitly chooses publication, with publishedBy recorded. Neither an internally autonomous S4 nor integrated first-party parent-mode completion is yet proven. - Supporting / enforcement mechanisms: RunOps Trace fields, strict trace candidate eligibility, source workflow pin, AI Coding task/artifact acceptance, Runtime DRAFT and validation, AgentConfig publish and tool version pin. - Closure path: A particular successful production trace → eligibility filter → human-created AI Coding task → AI-generated validated DRAFT with published=false → [separate human review/replay/publication and Agent attachment] → new ACTIVE Agent config and subsequent selected Workflow; the bracketed bridge must be evidenced as one function-specific authority-return path before positive grading. - Why this is / is not agent-owned: Only a proposed option is model-assisted; one path intentionally stops at DRAFT and never autonomously publishes. Presence of a separate publish API is not automatically evidence of completed S4 adaptation. - Evidence: eligible; candidate; provider; provider; provider; draft; attach; attach; enter. - Basis: Explicit first-party source supports real prospective candidate construction; the decisive parent-return boundary is unresolved. - Confidence: Moderate for draft option path, low for S4 closure. - Caveats: Do not call this proven S4=A/C/P without checking whether the operator publication/attachment chain actually forms a coherent first-party future-capability feedback relationship.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No function-specific legitimate ultimate-purpose/identity governance loop proven inside the packaged ReachAI runtime despite extensive access control. - Disturbance / variety regulated: Business permissions, tool risk, project/tenant identity and approval boundaries; these are operational trust/risk decisions, not an evidenced ultimate organizational ethos dispute. - Decisive decision or feedback right: Static policy profile, verified business identity and one-time per-tool approval constrain runtime acts; operator can publish Agent configuration. These do not identify or settle an ultimate system-identity purpose conflict via authoritative returned policy. - Decision owner: Application administrator and trusted business principal for configuration/approval; deterministic risk Guard enforces inherited policy. - Supporting / enforcement mechanisms: Tool ACL, project/tenant scope, READ/WRITE/IRREVERSIBLE risk modes, approval sessions, configuration publish and traces. - Closure path: Trusted identity → Guard allow/deny/confirm → operation or paused task returns; no separate ultimate-identity issue → legitimate S5 adjudication → accepted policy → governing subsequent operation chain established. - Why this is / is not agent-owned: Neither an autonomous ReAct planning choice nor a human confirming a WRITE tool owns ultimate organizational identity. - Evidence: policy; policy; attach; agent. - Basis: Explicit operational policy and authority-partition review; bounded negative for first-party S5. - Confidence: Medium-high for application-boundary conclusion. - Caveats: Business institution/user may provide upstream human-owned S5 outside the first-party harness; OSS maintainers are another separate organization.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f7149edec3a9174689baebee2fc9b1cf01f49ee7/assessments/reachai-enterpriseagentframework.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f7149edec3a9174689baebee2fc9b1cf01f49ee7\">f7149ed &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-28T13:40:25Z\"><th scope=\"row\"><a href=\"https://github.com/aiming-lab/AutoHarness\" target=\"_blank\" rel=\"noopener\">AutoHarness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/aiming-lab/AutoHarness/tree/3561e468f9ca9f9bf282512e695bd32e4e90fef4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3561e468f9ca9f9bf282512e695bd32e4e90fef4\">3561e46 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously interpret a user task and produce an operational result through iterative model/tool execution. - Disturbance / variety regulated: heterogeneous task intent, workspace state, tool results/errors, context limits and project-specific implementation uncertainty. - Decisive decision or feedback right: decide the next model-driven action/tool use and when the requested operational task has been completed. - Decision owner: the model-driven AgentLoop in the standard distribution. - Supporting / enforcement mechanisms: tool registry/execution, context management, governance pipeline, risk/permission checks, hooks, turn governor, audit logging and optional parent constitution. - Closure path: task → model decision → governed tool action → observed result → later model decision → returned task outcome. - Boundary reachability: AgentLoop is a directly documented/installable first-party entry point; no repository-development actor is required to expose its operating discretion. - Why this is / is not agent-owned: deterministic governance can permit/block/enforce actions, but the model-driven loop owns the substantive task/action decisions inside those constraints. - Evidence: autoharness/agentloop.py; README.md; autoharness/core/pipeline.py. - Basis: explicit + structural. - Confidence: high. - Caveats: model inference is external-provider execution and constitutions/tools are parent-configured, but the shipped runtime still exposes autonomous S1 decision/action closure.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes disturbance-specific coordination among distinct S1 units at this recursion. - Disturbance / variety regulated: no qualifying inter-S1 interference/conflict/oscillation is established by the reviewed standard distribution. - Decisive decision or feedback right: no S2-specific coordination decision right is established. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: TeamMailbox, message/broadcast transport, shutdown request/response, plan-approval response, team config/status, fork/background execution and coordinator delegation. - Closure path: messages can affect a receiving agent, but no first-party path ties them to a concrete inter-S1 disturbance, a response selected to attenuate that disturbance, and feedback of the coordination result into later S1 behaviour. - Why this is / is not agent-owned: swarm members may communicate autonomously, but communication/lifecycle protocol alone is below the Profile 0.2.4 S2 functional threshold; ownership classification therefore does not begin. - Evidence: autoharness/agents/swarm.py; docs/concepts/agents.md; docs/guides/multi-agent.md. - Basis: current-contract same-ref correction. - Confidence: high. - Caveats: downstream applications can use the mailbox to implement genuine conflict regulation; that is a separate composed system unless a first-party S2-specific relation is supplied and reachable here. - Distinct S1 units: swarm/fork/background workers can be distinct operational agents. - Inter-S1 disturbance: not established beyond hypothetical disagreement, overlap or lifecycle coordination. - Attenuating coordination relation: not established; mailbox and handshake primitives are generic transport/lifecycle mechanisms. - Feedback into subsequent S1 behaviour: generic messages can change later behaviour, but no evidence ties that change to resolution of a qualifying inter-S1 disturbance. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: it is not; the credited evidence is communication, lifecycle and delegation infrastructure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function is established over a portfolio of S1 resources, commitments, priorities or constraints. - Disturbance / variety regulated: not established as S3 at this recursion. - Decisive decision or feedback right: not established for whole-system current regulation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: coordinator-mode dispatch, turn governor, budgets/permissions, model routing, team member status and deterministic governance controls. - Closure path: not applicable as S3. - Why this is / is not agent-owned: a coordinator can decompose/delegate one task and deterministic controls can enforce preselected limits, but the reviewed evidence does not establish whole-system current visibility plus discretionary authority over shared resources/commitments/priorities on behalf of the organization as a whole. - Evidence: docs/concepts/agents.md; docs/guides/multi-agent.md; autoharness/core/pipeline.py. - Basis: structural absence review. - Confidence: high. - Caveats: manager/coordinator naming and hard enforcement are not S3 ownership shortcuts.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Claim being audited: the producing agent&#39;s claim that the requested implementation/work is complete and correctly verified. - Ordinary reporting path: the producing AgentLoop returns its own task result and ordinary tool observations to the caller. - Complementary access path: the separately invoked built-in Verification agent directly runs build/tests/lint/type checks and adversarial workspace probes; VerificationEngine can independently compare claimed results with recorded tool-call/result evidence. - Independence boundary: the verifier is a distinct first-party agent role/evaluation path with its own prompt and direct workspace evidence, rather than merely trusting the producer&#39;s completion report; forked history can be shared, so independence is complementary-evidence rather than complete informational isolation. - Who acts on findings: the embedding application/coordinator receives PASS/FAIL/PARTIAL findings and must compose corrective execution and re-verification, which is why the published ownership remains constructor C. - Function: challenge an operational completion/quality claim using materially different direct evidence from the project/workspace rather than relying on the producing agent&#39;s ordinary report. - Disturbance / variety regulated: false completion, verification avoidance, superficially passing work, missed edge cases, unrun tests/build/lint/type checks and claims inconsistent with actual tool-result evidence. - Decisive decision or feedback right: produce an audit judgment such as PASS, FAIL, or PARTIAL from direct build/test/lint/type-check/adversarial observations; the deterministic verification surface can likewise flag claim/evidence mismatch from audit history. - Decision owner: constructor path. AutoHarness supplies a specialized autonomous Verification-agent definition and explicit verification APIs, while the embedding developer/application still decides when that actor is invoked and must compose its findings into corrective authority/closure. - Supporting / enforcement mechanisms: fork/background execution, direct Read/Grep/Glob/Bash access, audit records, VerificationEngine, deterministic verdict/evidence structures and parent permissions. - Closure path: producing-agent result → separately invoked Verification agent or verification engine obtains complementary evidence → audit verdict/findings return to the caller; FAIL/PARTIAL → corrective execution → re-verification must still be composed downstream. - Boundary reachability: the Verification profile, getbuiltinagent(&quot;verification&quot;), verification engine and documented post-implementation pattern are shipped in the standard package; the path does not depend on repository CI or maintainer review. - Why this is / is not agent-owned: the built-in verifier can autonomously gather and judge complementary evidence, but no standard out-of-box loop gives it closed corrective authority over the producer after a failed audit. That missing composition keeps the published state at C, not A. - Evidence: autoharness/agents/builtin.py; docs/guides/multi-agent.md; autoharness/core/verification.py; autoharness/core/pipeline.py verifysession(). - Basis: explicit + structural. - Confidence: high. - Caveats: forked verification may inherit parent conversational history, so independence is role/evidence based rather than complete informational isolation. Its fresh direct workspace checks materially differ from ordinary self-report, but the caller still owns the final corrective composition.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective intelligence loop develops organizational adaptation options and returns them into current capability. - Disturbance / variety regulated: not established as S4. - Decisive decision or feedback right: not established for future-oriented adaptation. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: model routing, context management, diagnostics, hooks, session trust and configurable agents can alter current execution but do not establish future/environment modeling. - Closure path: not applicable as S4. - Why this is / is not agent-owned: current-task planning, runtime diagnostics and configurable extension are not evidence of an outside-and-then adaptation conversation with present S3 capability. - Evidence: AgentLoop, model routing, pipeline and multi-agent configuration surfaces. - Basis: structural absence review. - Confidence: high. - Caveats: an AutoHarness application could build research/self-improvement agents on top of these primitives; that downstream adaptation is not inherited by the generic distribution.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy closure is established at the AutoHarness application recursion. - Disturbance / variety regulated: not established as an identity/ultimate-policy dispute or adaptation/current-control tension requiring S5 closure. - Decisive decision or feedback right: constitutions, risk thresholds, permissions, hooks and agent-role definitions are authored/configured by the parent developer/operator rather than decided through a shipped S5 loop. - Decision owner: application developer/operator outside the autonomous assessed runtime for these policy choices. - Supporting / enforcement mechanisms: YAML constitution, permission/risk engines, hook profiles, trust state and deterministic enforcement. - Closure path: parent configuration is loaded into subsequent operation, but no identity/ultimate-policy matter is raised, adjudicated by legitimate S5 authority through a first-party runtime path, and returned as an authoritative policy decision. - Why this is / is not agent-owned: the agent operates under policy; it does not own ultimate authority to redefine the organization&#39;s identity or policy at this recursion. - Evidence: autoharness/core/pipeline.py; constitution/permission configuration docs; built-in agent definitions. - Basis: structural absence review. - Confidence: high. - Caveats: parent authors plainly control configuration, but static policy text or ordinary tool approval does not establish published P without a complete identity/policy decision loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a696223c9150d2541054e48ee55cb3640e0cd68a/assessments/autoharness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a696223c9150d2541054e48ee55cb3640e0cd68a\">a696223 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-28T16:46:51+03:00\"><th scope=\"row\"><a href=\"https://github.com/HarnessLab/claw-code-agent\" target=\"_blank\" rel=\"noopener\">claw-code-agent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/HarnessLab/claw-code-agent/tree/167571da895b2a1a9e36ecfae2876984cef65e0d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 167571da895b2a1a9e36ecfae2876984cef65e0d\">167571d &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously perform coding and tool-mediated implementation/analysis tasks, including delegated child-agent subtasks. - Disturbance / variety regulated: heterogeneous coding requests, workspace/repository state, tool outputs/failures, context/session state and delegated subtask uncertainty. - Decisive decision or feedback right: select the next model-driven coding/tool action and produce the operational result for the assigned task. - Decision owner: the model-driven main or child coding agent at its operating boundary. - Supporting / enforcement mechanisms: tool runtime, sessions, Agent Manager lineage, child delegation, plans/tasks, dependency checks, file history and runtime state. - Closure path: task → model decision → tool/workspace action → observed result → subsequent model decision → returned outcome. - Boundary reachability: the autonomous agent loop and child delegation are standard first-party runtime paths, not repository-development-only actors. - Why this is / is not agent-owned: deterministic task/session machinery persists and sequences work, while the agent owns substantive coding/tool decisions. - Evidence: src/agentruntime.py; README.md; agent/tool runtime surfaces. - Basis: explicit + structural. - Confidence: high. - Caveats: parent prompts/configuration and the model provider constrain the operating space, but the shipped loop still exposes autonomous S1 discretion.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes disturbance-specific attenuation of interference/conflict/oscillation among distinct S1 units at the declared recursion. - Disturbance / variety regulated: no qualifying interaction-generated inter-S1 disturbance is established. A dependency relation describes required order; a team message records/forwards information. - Decisive decision or feedback right: no S2-specific coordination decision/feedback right is established. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: dependency-aware task blocking/topological batching, plan/task ownership/status, persisted teams, sender/recipient messages, child-agent groups and delegation. - Closure path: dependencies can delay a task until prerequisites complete and messages can influence later work, but neither is evidenced as a response to a concrete inter-S1 disturbance with a coordination result fed back into later S1 behaviour. - Why this is / is not agent-owned: ownership classification does not begin because the functional S2 witness is absent; the observed mechanisms are sequencing, state and communication. - Evidence: src/planruntime.py; src/taskruntime.py; src/teamruntime.py; src/agentruntime.py; PARITYCHECKLIST.md. - Basis: current-contract same-ref correction. - Confidence: high. - Caveats: a downstream system could use these primitives to build genuine coordination, but general composability is not C under Methodology 0.3.6. - Distinct S1 units: main/child agents and multiple delegated workers can constitute distinct operational units. - Inter-S1 disturbance: not established as actual or structurally evidenced interference/conflict/oscillation arising from their interaction. - Attenuating coordination relation: dependency ordering prevents invalid prerequisite order but is deterministic task sequencing, not a response relation to an evidenced inter-S1 disturbance; team messages are generic transport. - Feedback into subsequent S1 behaviour: task completion and messages can affect later work, but not as feedback from an S2-specific disturbance-attenuation decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: it is not; the evidence is precisely generic messaging, dependency sequencing and delegation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function is established over the organization-wide portfolio of S1 resources, commitments, priorities or constraints. - Disturbance / variety regulated: not established as S3 at this recursion. - Decisive decision or feedback right: not established for whole-system current regulation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: parent-task delegation, Agent Manager lineage/groups, task statuses/owners/dependencies, plan summaries and runtime/tool limits. - Closure path: not applicable as S3. - Why this is / is not agent-owned: these surfaces decompose and sequence work but do not establish a whole-current-system view plus discretionary authority over shared resources/commitments/priorities on behalf of the whole. - Evidence: src/agentruntime.py; src/planruntime.py; task/Agent Manager surfaces. - Basis: structural absence review. - Confidence: high. - Caveats: manager/owner/status labels are not S3 shortcuts.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no materially independent complementary audit path is supplied that challenges ordinary operational claims with different access and returns findings into corrective control. - Disturbance / variety regulated: not established as S3. - Decisive decision or feedback right: not established for an independent audit judgment. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: transcript/file history, tests, diagnostics and runtime event records expose evidence but are not an independent operating auditor. - Closure path: not applicable as S3. - Why this is / is not agent-owned: no first-party standard role/path separates an auditor from the producing operation and returns its findings into correction/re-verification. - Evidence: runtime history/diagnostic surfaces and repository tests considered as adjacent evidence only. - Basis: structural absence review. - Confidence: high. - Caveats: a downstream child agent can be prompted as a reviewer, but generic delegation does not establish first-party complementary-audit ownership.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no external-and-prospective intelligence loop develops adaptation options for the claw-code-agent organization and returns them into present capability. - Disturbance / variety regulated: not established as S4. - Decisive decision or feedback right: not established for organizational adaptation. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: search, planning, context compaction, remote triggers and runtime adaptation support current task execution. - Closure path: not applicable as S4. - Why this is / is not agent-owned: current-task planning/search does not establish environment/future modelling → adaptation option → present-capability change. - Evidence: search/planning/runtime surfaces at the pinned revision. - Basis: structural absence review. - Confidence: high. - Caveats: downstream agents may perform research, but their task output is not inherited as organizational S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy closure is established at this recursion. - Disturbance / variety regulated: not established as an identity/ultimate-policy matter. - Decisive decision or feedback right: prompts, policies, permissions, budgets and runtime configuration remain parent/application authored. - Decision owner: developer/operator outside the autonomous assessed runtime for those choices. - Supporting / enforcement mechanisms: prompt/configuration, permission/policy hooks, budgets and tool restrictions. - Closure path: static/parent configuration constrains later operation, but no identity-level issue reaches legitimate S5 authority and returns as an authoritative policy decision through a first-party loop. - Why this is / is not agent-owned: agents operate under configured policy rather than owning ultimate organizational identity/policy. - Evidence: runtime configuration/policy surfaces at the pinned revision. - Basis: structural absence review. - Confidence: high. - Caveats: operator configuration power alone does not establish published P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/e2b8d19b06e741c996d654c02106888d17c8f622/assessments/claw-code-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit e2b8d19b06e741c996d654c02106888d17c8f622\">e2b8d19 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-13T21:44:59+03:00\"><th scope=\"row\"><a href=\"https://github.com/avala-ai/agent-code\" target=\"_blank\" rel=\"noopener\">Agent Code</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-13\">2026-10-13</time></td><td class=\"review-ref\"><a href=\"https://github.com/avala-ai/agent-code/tree/2734ab5f18939b20c774b39c4406788383e35255\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 2734ab5f18939b20c774b39c4406788383e35255\">2734ab5 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform discretionary local software engineering investigation, editing, testing and tool choice for a user coding objective. - Disturbance / variety regulated: uncertain repository state, inconsistent test/tool output, context gaps, tool permission failures, partial implementation work. - Decisive decision or feedback right: model selects specific calls/arguments and subsequent repair or investigation based on returned local execution evidence; write-capable general-purpose children independently implement assigned subtasks. - Decision owner: active model in the main QueryEngine or a spawned model&#39;s own independent query loop; not the tool dispatcher. - Supporting / enforcement mechanisms: provider transport, Rust query turn management, local tool executor, permission rules, session/history, worktree handling. - Closure path: user task → model selects file/shell/edit actions → first-party tools operate on repository → tool/test results return to model context → next decision or completion. - Boundary reachability: agent, agent -p, TUI/ACP/HTTP product entrypoints reach the library QueryEngine; built-in Agent delegates via shipped tools, not solely tests. - Why this is / is not agent-owned: the runtime enforces tools and displays results but does not select context-sensitive engineering solutions absent the model. - Evidence: README.md; mod.rs; agent.rs; executor.rs; coordinator.rs - Basis: explicit / structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no sufficiently supported first-party feedback loop that identifies specific harmful inter-S1 interaction/oscillation and changes affected siblings&#39; subsequent coding operations. - Disturbance / variety regulated: concurrent write-capable children could edit a common repository or duplicate work; MAP security-scan workers could share an execution quota, but the evidence shows separate read-only shards rather than an executed interference-correction route among competing coding S1s. - Decisive decision or feedback right: registry/list/parallel dispatch and subprocess completion do not show conflict-sensitive corrective decision; SendMessage is a stub in the product tool layer. - Decision owner: none demonstrated for an S2-specific conflict response; deterministic task batching and capacity limits serve tool scheduling and analysis. - Supporting / enforcement mechanisms: agent registry, child-context/worktree isolation, asynchronous team join, MapReduce file partitions and semaphore, task result metadata. - Closure path: spawned tasks return their own results or scan findings to the caller; no demonstrated inter-S1 disturbance sensor → attenuating correction → affected S1 feedback is wired across the declared supported modes. - Why this is / is not agent-owned: parallel processing and one-way report aggregation do not automatically supply S2&#39;s conflict-specific correction; preventing two read-only scan workers from modifying the same file does not establish that they were independently conflicting. - Evidence: agent.rs; coordinator.rs; sendmessage.rs; mod.rs; batch.rs; orchestrator.rs; executor.rs - Basis: structural / explicit placeholder comment -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material whole-current operational manager demonstrated at a subordinate multi-S1 system level. - Disturbance / variety regulated: competing live coding commitments, worker failures, current resource/task tradeoffs requiring corrective assignment. - Decisive decision or feedback right: no executable model-owned whole-team supervisory decision is evidenced across an up-to-date collective roster/commitments with applied corrective return. - Decision owner: primary caller delegates its current task; deterministic team collector reports completion, but neither owns managerial whole-current decisions proven here. - Supporting / enforcement mechanisms: spawned agent result aggregation, task status, workflow commands, separate MapReduce reducer&#39;s cross-shard synthesis. - Closure path: child output comes back to the requesting coding agent and scan REDUCE aggregates findings; no distinct current-management choice that reassigns active S1 commitments on collective information and feeds back to execution was established. - Why this is / is not agent-owned: a parent handing out one-time subtasks and aggregating reports is task execution; MAP/REDUCE synthesis determines the scan output, not live inside-and-now metasystem management. - Evidence: mod.rs; agent.rs; coordinator.rs; executor.rs; orchestrator.rs; securityscan.rs - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no separately owned first-party evidence auditor with a demonstrated return into corrective management of this coding-agent organization&#39;s claims. - Disturbance / variety regulated: unverified implementation correctness or false claims of code completion would call for an independent challenger with direct evidence. - Decisive decision or feedback right: the separate security-scan mode forms vulnerability judgments over source, but yields a standalone report/exit code to the invoker; no attached independent claim-checking review/decision with corrective management return is established for normal coding turns. - Decision owner: ordinary verification depends on coding model/operator; an optional standalone scan model can own its own security findings without becoming an S3 auditor of the coding organization&#39;s management. - Supporting / enforcement mechanisms: read-only MAP security scan, REDUCE report and command exit codes, optional model-driven review slash workflows and external CI. - Closure path: security-scan → human/CI-facing findings (at or above severity threshold), not evidenced as independent source-first audit → separate S3 owner decision → changed current coding workforce operation. - Why this is / is not agent-owned: review/audit vocabulary or a standalone scanner is not sufficient for a canonical complementary audit without actual corrective return; deterministic task tests and plugin review workflows are likewise not sufficient. - Evidence: securityscan.rs; orchestrator.rs; mod.rs; reduce.rs; coordinator.rs; mod.rs - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no separately evidenced adaptive future-capability decision/enactment cycle at the declared agent organizational boundary. - Disturbance / variety regulated: future provider/coding-task environment variation, new tools, changed engineering requirements. - Decisive decision or feedback right: no agentic strategic investment/organizational adaptation selection and return to changed capacity. - Decision owner: human/operator config and project maintainers control model/provider, built-in or custom agent definitions and skill/plugin ecosystems. - Supporting / enforcement mechanisms: persistent memory consolidation, history compaction, provider fallback, skill/manifests and scheduled tasks. - Closure path: memory and configuration can inform later task decisions, but prospective outside signal → deliberate capability revision → organizational implementation remains unestablished. - Why this is / is not agent-owned: remembering code details or switching provider on request does not mean choosing future organizational capabilities. - Evidence: README.md; consolidation.rs; schema.rs; mod.rs; mod.rs - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no ultimate mission, identity or binding constitutional policy owner within the product organization. - Disturbance / variety regulated: conflicts over organizational purpose beyond permission for local tool operations. - Decisive decision or feedback right: no legitimate S5 actor decides and enacts mission/identity conflict resolutions in the running agent system. - Decision owner: human operator and developer/project configuration set scope, allowed providers and permissions. - Supporting / enforcement mechanisms: permission rules, plan/read-only modes, protected paths, per-agent model/tool restrictions and sandbox. - Closure path: permission checks can deny a shell/file effect or allow one; no purpose/identity matter escalates to a constitutional decision owner and returns as binding policy to the organization. - Why this is / is not agent-owned: local code security and per-call approval are not ultimate policy/identity governance. - Evidence: README.md; mod.rs; coordinator.rs; schema.rs; agent.rs - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f11ef7f2f1472a72cb831d493ffa847cfa6a2121/assessments/agent-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f11ef7f2f1472a72cb831d493ffa847cfa6a2121\">f11ef7f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-13T20:10:26+03:00\"><th scope=\"row\"><a href=\"https://github.com/LiuMengxuan04/MiniCode\" target=\"_blank\" rel=\"noopener\">MiniCode</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-13\">2026-10-13</time></td><td class=\"review-ref\"><a href=\"https://github.com/LiuMengxuan04/MiniCode/tree/55dca55e13b7f34364893f3190914406be860b70\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 55dca55e13b7f34364893f3190914406be860b70\">55dca55 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform uncertain local developer coding work by choosing inspections, edits, commands, follow-up repairs and final response. - Disturbance / variety regulated: unknown repository structure and behavior, tool errors, incomplete modifications, shell/test feedback, and changing task-local context. - Decisive decision or feedback right: root model selects the next tool/coding action in response to actual returned tool results and goal/plan observations. - Decision owner: root coding agent/model, not static tool registry, permissions or local session store. - Supporting / enforcement mechanisms: CLI/TUI presentation, tool schemas, permission checks, edit review, context compaction and append-only sessions. - Closure path: model turn → selected read/search/edit/shell operation or denied permission → actual result → model continuation/repair/final. - Boundary reachability: standard CLI directly instantiates the first-party model/tool loop and built-in mutating coding tools; no external developer composition is required. - Why this is / is not agent-owned: removing model discretion leaves action primitives and safety gates but no adaptive code-edit choice after observations. - Evidence: README.md; ARCHITECTURE.md; agent-loop.ts; tool.ts; index.ts; permissions.ts; file-review.ts - Basis: explicit and structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no shipped regulation of a specific interference between multiple independently operating coding S1 units. - Disturbance / variety regulated: possible inter-worker conflicts are not materially presented in the read-only child architecture. - Decisive decision or feedback right: no inter-S1 conflict-response discretion or return channel is established at the declared recursion. - Decision owner: none evidenced for S2; root alone owns code writes, while children investigate independent read-only questions. - Supporting / enforcement mechanisms: three-worker concurrency cap, in-memory status, wait and cancel APIs. - Closure path: a child research report returns to root task choice, not to a dedicated cross-worker interference attenuation/return loop. - Why this is / is not agent-owned: task decomposition, multiple read-only investigations and bounded concurrent model calls cannot create a file-write collision among distinct first-party coding cells at this scope. - Evidence: ARCHITECTURE.md; sub-agents.ts; manager.ts; worker-prompt.ts; agent-loop.ts - Basis: explicit implementation boundary plus structural inspection -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no whole-current multi-S1 operational management of resources/priorities/commitments is established. - Disturbance / variety regulated: individual task limits, read-only child investigation statuses and completion of a user goal. - Decisive decision or feedback right: root selects its own subtasks and may close a research worker, but no separate whole-system current-control decision is evidenced. - Decision owner: root for coding delegation; human for user task and permission settings; deterministic manager for the fixed cap. - Supporting / enforcement mechanisms: agent roster, wait, abort, plan/Todo, goal criteria, per-turn step limits. - Closure path: child completion informs root&#39;s next coding turn, but no live organization-wide reprioritization or constraint return across independent S1 operations. - Why this is / is not agent-owned: a class named SubAgentManager and root tool scheduling are not proof of a whole-current metasystem; all edits stay with one root coding unit. - Evidence: ARCHITECTURE.md; manager.ts; sub-agents.ts; plan.ts; goal.ts; agent-loop.ts - Basis: explicit and structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no shipped independently commissioned complementary audit with findings returned to a distinct current-control owner. - Disturbance / variety regulated: potential incorrect implementing-agent claims that would warrant direct independent challenge. - Decisive decision or feedback right: no first-party independently assigned audit judgment and corrective governance return is evidenced. - Decision owner: root task model for ordinary review and repair, developer for edit approvals; generic read-only child can investigate any task but has no dedicated auditor authority. - Supporting / enforcement mechanisms: file-review diff approval, root verification commands, generic investigation/report path, tests as adjacent development infrastructure. - Closure path: read-only investigation report or diff-approval feedback may influence the same root task, but no distinct S3 audit finding/disposition pipeline to managerial control exists. - Why this is / is not agent-owned: an instruction to return findings on a user-assigned investigation is not an independent complementary audit contract; ordinary self-verification is not S3. - Evidence: worker-prompt.ts; manager.ts; sub-agents.ts; file-review.ts; ARCHITECTURE.md; agent-loop.ts - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no continuously available externally and prospectively oriented capability-adaptation decision loop. - Disturbance / variety regulated: changing model availability, tools and documentation, as opposed to coding task facts. - Decisive decision or feedback right: no agent or first-party parent selects future system adaptations based on environmental prognosis and returns them to current capability. - Decision owner: user installs/configures skills/models; agent chooses context and resources for current tasks only. - Supporting / enforcement mechanisms: layered memory, online search/fetch, skill manager, context compaction and goal tracking. - Closure path: new information informs the current coding goal or is persisted as user instructions; no prospective alternative/decision/return to organizational capability. - Why this is / is not agent-owned: project context and goal updates do not constitute VSM S4 future adaptation. - Evidence: ARCHITECTURE.md; memory.ts; web-search.ts; goal.ts; session.ts - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no ultimate-purpose identity-policy arbitration and binding return path is established. - Disturbance / variety regulated: constitutional identity conflicts beyond ordinary tool safety/approval. - Decisive decision or feedback right: human sets tasks and safety policy; no runtime S5 policy judgment owner. - Decision owner: user/parent outside session for purpose, permission and accepted changes. - Supporting / enforcement mechanisms: allow/deny lists, edit review, shell confirmation, project instruction memory and bounded child tools. - Closure path: human may approve a command or edit, affecting that one operation, but no identity-level proposal → authority → decision → subsequent governance change loop. - Why this is / is not agent-owned: static guardrails and user task approval differ categorically from S5 identity governance. - Evidence: permissions.ts; file-review.ts; worker-prompt.ts; ARCHITECTURE.md; memory.ts - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9993f371640eb79260b389e4abf495bd128739b1/assessments/liumengxuan04-minicode.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9993f371640eb79260b389e4abf495bd128739b1\">9993f37 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-12T16:37:10+03:00\"><th scope=\"row\"><a href=\"https://github.com/ultraworkers/claw-code\" target=\"_blank\" rel=\"noopener\">Claw Code</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-30\">2026-09-30</time></td><td class=\"review-ref\"><a href=\"https://github.com/ultraworkers/claw-code/tree/08106b0c3771ef5b4a5aa176acccd460e88b7325\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 08106b0c3771ef5b4a5aa176acccd460e88b7325\">08106b0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously transform software-engineering intent into repository analysis or changes through a first-party model/tool execution loop. - Disturbance / variety regulated: heterogeneous user goals, repository structure, source state, model responses, tool results and failures, permission outcomes, and intermediate findings that require context-sensitive choices rather than a fixed command script. - Decisive decision or feedback right: choose the next repository/tool action, interpret returned evidence, revise subsequent action selection, and decide when the turn is complete. - Decision owner: the model-backed agent actor operating through the first-party ConversationRuntime; the external provider supplies inference, while claw owns the reachable session/tool/feedback organization in which that discretion is exercised. - Supporting / enforcement mechanisms: Session; provider request/stream plumbing; built-in tool executor; permission policy/enforcer; hooks; iteration bound; usage tracking; automatic context compaction; filesystem/shell/search/MCP tools; CLI and session persistence surfaces. - Closure path: user prompt → first-party runtime builds a provider request from current session state → model selects an answer or tool call → claw permission-checks and executes the tool → tool evidence is appended to the session → the next model turn changes action based on that evidence → iteration ends when the model returns without further tool calls, producing an answer and/or repository effect. - Boundary reachability: the loop is the shipped core path for interactive REPL and one-shot claw prompt; a downstream developer does not need to compose the model/tool feedback cycle. - Why this is / is not agent-owned: if the model-backed actor is removed while the deterministic runtime, session and tool executors remain, the system retains mechanisms but loses the contextual choice of what to inspect/change next and when the coding turn is complete. The decisive S1 discretion is therefore agent-owned. - Evidence: rust/crates/runtime/src/conversation.rs; rust/crates/runtime/src/lib.rs; USAGE.md. - Basis: explicit + structural. - Confidence: high. - Caveats: provider/model intelligence is an external dependency. The assessment credits the first-party runtime closure, not unrelated organizational behavior inside Anthropic/OpenAI-compatible providers or other external agent products.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no complete first-party same-recursion coordination function was established in the reviewed standard-distribution boundary. - Disturbance / variety regulated: the repository structurally models one relevant disturbance — two lanes targeting the same branch and overlapping/nested module scopes — but the reviewed claw operating path does not close an attenuation loop from that detection into subsequent S1 behavior. - Decisive decision or feedback right: not established. detectbranchlockcollisions deterministically reports collisions; no standard production caller was found that decides and returns an isolation/reservation/reroute response to the affected native agent units. - Decision owner: not established. - Supporting / enforcement mechanisms: public BranchLockIntent / BranchLockCollision types and collision detector; task/team registry metadata; background native Agent construction; worker state; external OmX/OmO coordination described in repository documentation but excluded from the claw boundary. - Closure path: not established. The detector returns collision data to a caller, but the frozen first-party runtime does not wire that result into a coordination action that changes the conflicting S1 units&#39; subsequent operation. - Why this is / is not agent-owned: no S2 function is credited, so ownership is not classified. A disturbance-specific detector is stronger than generic messaging, but an unwired diagnostic surface does not satisfy the required feedback witness. - Evidence: rust/crates/runtime/src/branchlock.rs; rust/crates/runtime/src/lib.rs; rust/crates/runtime/src/taskregistry.rs; PHILOSOPHY.md. - Basis: structural absence conclusion. - Confidence: high. - Caveats: the public collision detector is a plausible future S2 constructor ingredient. It is not published as C here because Methodology 0.3.6 requires the S2 function itself — including feedback into subsequent S1 behavior — to be established before ownership classification.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no boundary-reachable whole-system current-control function over the focal organization was established. - Disturbance / variety regulated: per-lane completion, stale/diverged branch conditions, retries, review status, permission decisions and worker lifecycle are represented by mechanisms, but no standard actor was found that integrates a whole-system current view and exercises discretionary resource/commitment/priority control on behalf of the whole. - Decisive decision or feedback right: not established at S3 scope. - Decision owner: not established. - Supporting / enforcement mechanisms: task/lane registry state; worker create/observe/restart/terminate surfaces; permission enforcement; workspace-test branch-divergence preflight; PolicyEngine rule/action types; and lane-completion helpers. - Closure path: not established for S3. Static permission/preflight mechanisms can block local actions, and registry APIs can mutate individual records, but no current whole-system decision loop was reconstructed. - Why this is / is not agent-owned: deterministic enforcement of local constraints and per-lane lifecycle is not sufficient to establish S3, and no autonomous or parent current-control owner closes the missing function in the reviewed mode. - Evidence: rust/crates/runtime/src/taskregistry.rs; rust/crates/runtime/src/policyengine.rs; rust/crates/tools/src/lanecompletion.rs; rust/crates/tools/src/lib.rs. - Basis: structural absence conclusion. - Confidence: high. - Caveats: PolicyEngine exposes expressive retry/rebase/merge/escalate/block actions, but the inspected context is per-lane and the stronger completion glue at this revision is explicitly dead-code. Component vocabulary and deterministic authority do not substitute for an operational S3 closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: provide a first-party construction path for a materially separate verification actor to challenge claims made by ordinary coding operation using direct repository/test/search evidence. - Disturbance / variety regulated: a focal coding agent can report a change as correct or complete despite defects, missed constraints, failing tests or evidence it did not inspect in its ordinary session. - Decisive decision or feedback right: a separately instantiated Verification subagent can independently inspect repository artifacts and execute verification-capable tools, producing a persisted finding/result distinct from the focal agent&#39;s ordinary report; the standard distribution does not itself close those findings into mandatory corrective action. - Decision owner: constructor/control state C. The first-party runtime supplies the audit-specific autonomous actor and independent evidence path, while a caller/developer or higher-level workflow must still compose the returned finding into a corrective control loop. - Supporting / enforcement mechanisms: model-visible Agent tool; background thread/job; fresh Session::new(); separate ConversationRuntime; verification-specific system prompt/type; restricted verification tool set; persisted output and manifest; lane events/terminal result state. - Closure path: focal operation produces a claim/change → caller invokes Agent with Verification specialization → first-party code creates a separate session/runtime and the verifier directly inspects/tests/searches relevant evidence → verifier output is persisted and exposed via returned output/manifest paths → caller can read the finding and alter later operation. The final finding-to-correction leg is intentionally not treated as prewired standard closure, hence C rather than A. - Boundary reachability: Agent is a shipped built-in model-visible tool in the canonical Rust runtime; the verification specialization and its fresh runtime/session are created by first-party code without an external workflow framework. No OmX/OmO behavior is needed to instantiate this audit path. - Why this is / is not agent-owned: the complementary audit judgment itself is model-owned inside the independently instantiated verifier, but the assessed standard distribution leaves authority/closure from finding to subsequent corrective operation to composition. This is the Methodology&#39;s constructor case rather than a fully closed autonomous S3 loop. - Evidence: rust/crates/tools/src/lib.rs; rust/crates/runtime/src/conversation.rs; USAGE.md. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: this assessment does not import OmO&#39;s documented cross-agent verification loops. It credits only the native verification constructor whose separate runtime/session and persisted evidence path are present in claw. No mandatory repair/retry edge driven by the verifier was found in the standard path. - Claim being audited: correctness/completeness of repository work or claims produced by the focal coding-agent operation. - Ordinary reporting path: the focal ConversationRuntime&#39;s own assistant/tool sequence and final output. - Complementary access path: a native Verification Agent job with a fresh session/runtime and direct bash/read/glob/grep/web/search/tool access to repository and external evidence. - Independence boundary: separate session, runtime instance, background job, prompt specialization and result artifact; model/provider may still be configured from the same family, so this is functional/session independence rather than organizational-provider independence. - Who acts on findings: the invoking focal agent, developer or higher-level first-party/external workflow after reading the persisted verifier result; corrective return is not automatically enforced by the native constructor.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party externally and prospectively oriented adaptation loop was established in the reviewed claw operating boundary. - Disturbance / variety regulated: the runtime can fetch current web/MCP information and retain session/context/skills, but these mechanisms serve present tasks rather than a demonstrated future-oriented sensing → option-development → capability-change cycle. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: WebFetch/WebSearch/MCP tools; session persistence and compaction; project/user skill lookup; configuration; recovery/policy helpers; repository-development learning and evolution artifacts outside the product boundary. - Closure path: not established for S4. - Why this is / is not agent-owned: present-task research and retained context do not by themselves constitute outside-and-then adaptation, and no standard agent owns a prospective capability-change loop returning into present claw capability. - Evidence: rust/crates/tools/src/lib.rs; USAGE.md; PHILOSOPHY.md. - Basis: structural absence conclusion. - Confidence: high. - Caveats: the repository itself was developed through a broader agent-managed organization and exposes flexible skills/configuration, but development history and generic extensibility are adjacent evidence, not a boundary-reachable S4 function of the shipped runtime.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy decision loop was established at the declared claw recursion. - Disturbance / variety regulated: permission modes, system prompts, provider settings, configuration rules and user approvals constrain ordinary operation, but no identity-level dispute/proposal is routed to an ultimate authority and returned as governing policy for subsequent operation. - Decisive decision or feedback right: not established at S5 scope. - Decision owner: not established. - Supporting / enforcement mechanisms: system prompt construction; permission policy/enforcer; config/rules imports; approval-token and operator controls; user task intent; repository maintainer/development governance outside the runtime boundary. - Closure path: not established for identity/ultimate policy. - Why this is / is not agent-owned: operational safety/configuration choices do not become S5 merely because they can block tools or require human action. No autonomous or parent-governed identity closure was found in the assessed mode. - Evidence: rust/crates/runtime/src/lib.rs; rust/crates/runtime/src/policyengine.rs; USAGE.md; PHILOSOPHY.md. - Basis: structural absence conclusion. - Confidence: high. - Caveats: the human-directed development philosophy is not imported as a runtime S5 parent arrangement. A user deciding a task or permission escalation is an operational event, not by itself an identity/ultimate-policy decision at this recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/5b7abf87c90d2ec237a7e7ed73d39f6da9b629ef/assessments/claw-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 5b7abf87c90d2ec237a7e7ed73d39f6da9b629ef\">5b7abf8 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-28T23:51:28Z\"><th scope=\"row\"><a href=\"https://github.com/InternScience/ResearchHarness\" target=\"_blank\" rel=\"noopener\">ResearchHarness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-29\">2026-09-29</time></td><td class=\"review-ref\"><a href=\"https://github.com/InternScience/ResearchHarness/tree/72e8a44737aadabc8c3f9e5c7ea76883b9c7032f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 72e8a44737aadabc8c3f9e5c7ea76883b9c7032f\">72e8a44 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform open-ended local/web agent work through a model-driven decision/action/observation loop. - Disturbance / variety regulated: user goals, changing workspace/web state, tool outputs/errors, provider responses, missing evidence, context pressure and runtime limits encountered during a trajectory. - Decisive decision or feedback right: choose the next substantive answer or native tool action in response to current context and returned observations. - Decision owner: the autonomous model-driven ResearchHarness agent actor. - Supporting / enforcement mechanisms: reactagent.py, native tool schemas/dispatcher, bounded workspace paths, read-tool concurrency partitioning, retries/timeouts, session state, traces, context compaction and max-round/runtime limits. - Closure path: user/client prompt → model turn → model-selected tool call → first-party tool execution → result enters messages/session state → next model turn observes the result and revises/continues → terminal answer or bounded stop. - Boundary reachability: the loop is the core first-party runtime used by CLI, Python embedding, UI and API serving; no development-only or external orchestration actor is required beyond the configured model provider and environment tools. - Why this is / is not agent-owned: deterministic host code executes and bounds actions, but the model chooses the substantive next action. Removing that actor leaves tools/session machinery without the goal-directed operational decision loop. - Evidence: agentbase/reactagent.py; README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: external provider internals are not imported; S1 credit rests on ResearchHarness owning the first-party tool execution and observation-return loop around the model.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no inter-S1 coordination function is established at the reviewed recursion. - Disturbance / variety regulated: no first-party topology with interacting distinct S1 units and a concrete cross-unit conflict/oscillation was found. - Decisive decision or feedback right: not established for S2. - Decision owner: not established. - Supporting / enforcement mechanisms: independent API-run thread-pool concurrency, adjacent read-only tool parallelism and serialization of mutation-sensitive tool calls within one agent turn. - Closure path: these mechanisms schedule execution inside or between independent requests but do not reconstruct a distinct-S1 disturbance → coordination response → changed later S1 behavior loop. - Why this is / is not agent-owned: multiple tool calls and concurrent API requests are not multiple coordinated operational units. The repository explicitly presents one main ReAct loop rather than a multi-agent orchestration layer. - Evidence: README.md; agentbase/reactagent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: an upper-layer framework may instantiate several ResearchHarness agents, but that organization is outside this repository&#39;s standalone boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no first-party whole-system current-control function is established above the single agent run. - Disturbance / variety regulated: one run has round/time/token/retry boundaries and optional interactive clarification, but no portfolio of current S1 commitments/resources is presented to a whole-system controller. - Decisive decision or feedback right: not established for S3. - Decision owner: not established. - Supporting / enforcement mechanisms: runtime limits, tool restrictions, request-local model/tool options, interruption, workspace confinement, AskUser and API concurrency limits. - Closure path: limits can stop or constrain an individual run, and a user can answer a clarification, but no whole-system current view → allocation/commitment/intervention judgment → changed organization-wide operation loop exists. - Why this is / is not agent-owned: deterministic limits are enforcement, not S3 ownership; AskUser is local task clarification rather than current-control authority over multiple S1 units. - Evidence: agentbase/reactagent.py; agentbase/prompts/systembase.md; README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: host-level orchestration/control can be layered around the base harness but is not inherited into this assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no sufficiently independent complementary audit path is established. - Disturbance / variety regulated: the agent may make incorrect claims or incomplete work, but the standard distribution does not add a separate audit actor/path that challenges ordinary S1 reporting through materially different access to operational reality. - Decisive decision or feedback right: not established for S3. - Decision owner: not established. - Supporting / enforcement mechanisms: direct tool observations, workspace rereads, traces, session state, prompt instructions to verify claims, benchmark/end-to-end tests and customizable completion hooks. - Closure path: tool results and verification reads feed directly back into the same producing S1 loop; traces record that loop. No distinct ordinary-report claim → complementary evidence → audit judgment → corrective-return path is packaged. - Why this is / is not agent-owned: self-verification by the producing agent and ordinary tool feedback do not establish complementary audit independence. Repository tests/benchmarks are development/evaluation surfaces outside the product-runtime boundary. - Evidence: agentbase/prompts/systembase.md; agentbase/reactagent.py; agentbase/base.py. - Basis: explicit + structural. - Confidence: high. - Caveats: an upper layer may override completion hooks or add a reviewer, but generic extensibility is not a first-party S3-specific constructor.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party outside-and-then adaptation loop is established. - Disturbance / variety regulated: no path was found that senses external/future change, develops an adaptation option and returns that option to modify later organizational capability. - Decisive decision or feedback right: not established for S4. - Decision owner: not established. - Supporting / enforcement mechanisms: context compaction, local plan.md/memory.md, web/research tools, provider/model request options and extensible prompts/tools. - Closure path: compaction summarizes older turns for continuation of the current task; plan/memory files preserve current-task state. Neither constitutes a future-oriented adaptation decision returned into durable capability. - Why this is / is not agent-owned: the compaction prompt is explicitly working memory for continued execution and says workspace files remain authoritative. Web search/research during a task is S1 environmental work unless it enters a prospective organizational adaptation loop. - Evidence: agentbase/contextcompact.py; agentbase/prompts/systembase.md; agentbase/sessionstate.py. - Basis: explicit + structural. - Confidence: high. - Caveats: the repository describes itself as a possible meta-harness for future optimization, but repository-development optimization is not a first-party product-runtime S4 organ.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: the base system prompt, role addenda, tool restrictions, workspace safety rules and runtime configuration constrain operation but do not constitute an identity/constitutional issue resolved by legitimate ultimate authority. - Decisive decision or feedback right: not established for S5. - Decision owner: caller configuration supplies role prompts/tool sets and the shipped base prompt supplies static operating rules; no qualifying S5 authority path exists. - Supporting / enforcement mechanisms: system prompt composition, role-prompt files, tool lists, workspace confinement, API/CLI configuration and AskUser. - Closure path: configuration affects later run behavior, but no identity/ultimate-policy matter → authoritative decision → returned organization-wide policy loop is established. - Why this is / is not agent-owned: static prompts and safety constraints are explicitly insufficient under the Profile; AskUser handles task-level missing information/approval rather than constitutional authority. - Evidence: agentbase/prompts/systembase.md; agentbase/base.py; README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: an upper-layer application can impose governance around ResearchHarness, but that authority belongs to the upper layer&#39;s recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/66010e42438d495b1dfbc46df8d47ba07cb79eee/assessments/researchharness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 66010e42438d495b1dfbc46df8d47ba07cb79eee\">66010e4 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-21T20:14:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/raphaelchristi/harness-evolver\" target=\"_blank\" rel=\"noopener\">Harness Evolver</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/raphaelchristi/harness-evolver/tree/87fa7612358acccb01d34abf72426a7e47329642\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 87fa7612358acccb01d34abf72426a7e47329642\">87fa761 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: execute the harness-evolution transformation by diagnosing target failures, generating and implementing candidate changes, evaluating/selecting candidates, installing accepted target changes, and iterating. - Disturbance / variety regulated: target-harness design uncertainty, benchmark failures, trace-derived failure modes, alternative implementation hypotheses, and candidate performance variation. - Decisive decision or feedback right: choose a substantive diagnosis/change strategy for the target harness and produce a candidate implementation or abstain; the enclosing evolution loop then selects and installs an accepted candidate. - Decision owner: model-driven proposer/evolution actors operating under the shipped first-party role and evolve-loop contract. - Supporting / enforcement mechanisms: isolated Git worktrees, LangSmith-backed evaluation, constraint/efficiency gates, selection tools, archive/history, regression tracking and merge machinery. - Closure path: evidence from the current target state → proposer diagnosis and candidate mutation → candidate evaluation/selection → accepted candidate merged into the target harness → changed target becomes the baseline/context for later evolution iterations. - Boundary reachability: the standard /harness:evolve procedure directly instantiates the shipped proposer role and first-party tools; no downstream organizational component is required to expose proposer discretion or the candidate-selection/merge path. - Why this is / is not agent-owned: deterministic tools isolate, evaluate, gate and merge candidates, but the substantive hypothesis and code-change choice is made by the model-driven proposer. The target harness being changed is environment; its internal organization is not imported into Harness Evolver&#39;s own vector. - Evidence: skills/evolve/SKILL.md; agents/harness-proposer.md; docs/ARCHITECTURE.md. - Basis: explicit + structural. - Confidence: high. - Caveats: external model/coding-agent hosts execute the supplied role contract, and generated candidate harnesses remain separate systems-in-focus.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes regulation of a concrete interference, conflict or oscillation among distinct operational S1 units at this recursion. - Disturbance / variety regulated: not established as S2. - Decisive decision or feedback right: not established for S2. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: parallel proposer waves, isolated worktrees, staged execution, shared strategy/archive context and later candidate comparison reduce collision in the search process but do not establish a peer mutual-adjustment function by themselves. - Closure path: not applicable as S2. - Why this is / is not agent-owned: worktree isolation prevents candidate-state collision and wave ordering structures search; the evidence does not show an S2-specific actor observing destructive inter-S1 interference/oscillation and feeding a coordination response back into subsequent peer behavior. - Evidence: skills/evolve/SKILL.md; docs/ARCHITECTURE.md. - Basis: structural absence review. - Confidence: high. - Caveats: a downstream orchestration of proposer agents could add an S2 loop, but generic parallelism and isolation are insufficient at the reviewed boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct first-party whole-organization current-control function is established over a portfolio of operational S1 commitments. - Disturbance / variety regulated: not established as S3 at this recursion. - Decisive decision or feedback right: not established for whole-current-system regulation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: candidate selection, constraint/efficiency gates, iteration stop criteria, retry/cleanup and Architect triggers regulate the primary evolution process but do not by themselves create a distinct whole-organization current-control owner. - Closure path: not applicable as S3. - Why this is / is not agent-owned: the selection/gating machinery governs which candidate advances inside the S1 evolution transformation. The reviewed evidence does not establish a separate actor with a whole-current view plus discretionary authority over shared resources, commitments, priorities or multiple operational units on behalf of the organization as a whole. - Evidence: skills/evolve/SKILL.md; docs/ARCHITECTURE.md. - Basis: structural absence review. - Confidence: medium-high. - Caveats: role names such as Architect/Consolidator and deterministic gates are not promoted to S3 without the required function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: independently challenge whether ordinary evaluator/benchmark scores correspond to substantive target-harness quality rather than evaluator gaming, blind spots or score inflation. - Disturbance / variety regulated: high-scoring but substantively wrong outputs, hallucination/format gaming, evaluator blind spots, suspicious score jumps and inflation that can mislead ordinary candidate selection. - Decisive decision or feedback right: judge whether the ordinary evaluation regime is being gamed or misses a material quality dimension and choose a stricter evaluator/check intended to close that blind spot. - Decision owner: the autonomous Critic owns the complementary audit judgment and chooses the corrective evaluator within the supplied audit role; the final executable return from arbitrary stored evaluator definition to later scoring remains uncomposed in the pinned runtime. - Supporting / enforcement mechanisms: Critic trigger conditions, direct access to best-run outputs/evaluator behavior/score history, addevaluator.py, .evolver.json evaluator storage, criticreport.md, and config validation. - Closure path: Critic finding → Critic invokes addevaluator.py → evaluator name/definition is persisted in .evolver.json. The first-party path stops short of demonstrated operational closure for arbitrary Critic-added code evaluators: runeval.py::loadevaluators() does not load config[&quot;codeevaluators&quot;], while harness-evaluator handles only correctness/conciseness. A developer/composer must wire the stored evaluator definition into executable later evaluation/selection feedback. - Boundary reachability: the Critic role, Critic trigger and addevaluator.py are shipped and reachable from the standard evolve procedure, so the S3-specific construction path is first-party. The missing evaluator-execution edge is not borrowed from an adjacent project or hypothetical downstream integration. - Why this is / is not agent-owned: the audit judgment itself is agent-owned and sufficiently separated from ordinary proposer/evaluator production. However, Methodology A requires the decisive audit/feedback loop to be operationally closed; persisting a corrective evaluator definition that the shipped evaluator path does not execute is insufficient. The function-specific first-party path therefore satisfies C, not A. - Evidence: agents/harness-critic.md; tools/addevaluator.py; tools/runeval.py; agents/harness-evaluator.md; skills/evolve/SKILL.md. - Basis: explicit + structural. - Confidence: high. - Caveats: the correction does not claim the Critic lacks independence or discretion. It narrows only the previously overstated corrective closure. A later upstream revision that actually executes Critic-added evaluator definitions can be reassessed separately. - Claim being audited: that high evaluator/benchmark scores represent substantive target-harness quality rather than exploitation of the current scoring regime. - Ordinary reporting path: candidate runs are scored by the normal configured evaluation path and those scores feed candidate comparison/selection. - Complementary access path: the separate Critic inspects best-run outputs, evaluator behavior and cross-iteration score history specifically to challenge the ordinary score path and diagnose blind spots/gaming. - Independence boundary: the Critic is a separately supplied role from proposer and ordinary evaluator, is not tasked to optimize a candidate directly, and receives evidence specifically for adversarial audit of the evaluation regime. - Who acts on findings: the Critic itself writes the corrective evaluator configuration. At the pinned revision no first-party later runtime actor is demonstrated to execute arbitrary stored codeevaluators definitions into subsequent scores, so the final corrective return still requires composition.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party outside-and-then intelligence loop is established for Harness Evolver itself. - Disturbance / variety regulated: not established as S4 at the assessed recursion. - Decisive decision or feedback right: not established for external/future adaptation of the Harness Evolver organization. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: trace analysis, benchmark-driven improvement, strategy/lens synthesis, archive mining, regression history, Architect/Consolidator roles and evolution memory improve the current target-search operation but remain internally oriented to that operation/distribution. - Closure path: not applicable as S4. - Why this is / is not agent-owned: learning and self-improvement around the target benchmark are not promoted to S4 without a loop that senses external/future distinctions for the Harness Evolver organization and returns adaptation options into its present capability. - Evidence: skills/evolve/SKILL.md; docs/ARCHITECTURE.md; proposer/archive/memory paths. - Basis: structural absence review. - Confidence: high. - Caveats: the evolved target may gain future-facing capability, but target-harness adaptation is not imported as S4 of Harness Evolver.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy closure is supplied for the Harness Evolver organization. - Disturbance / variety regulated: not established as S5. - Decisive decision or feedback right: not established for ultimate organizational identity/policy. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: user-supplied objective, evaluator configuration, constraints, target score, iteration count and stop criteria bound the evolution search but do not form a first-party identity-policy loop. - Closure path: not applicable as S5. - Why this is / is not agent-owned: accepting configuration or enforcing goals does not establish runtime authority to define/revise the organization&#39;s ultimate purpose or constitutional policy. - Evidence: skills/evolve/SKILL.md; setup/configuration and gate paths. - Basis: structural absence review. - Confidence: high. - Caveats: human/operator authorship of the objective is environment/configuration, not automatically a published parent-governed S5 mode.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/96f7c3bc1fb72b27c2118db1f4953c5b1f75a868/assessments/harness-evolver.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 96f7c3bc1fb72b27c2118db1f4953c5b1f75a868\">96f7c3b &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T22:55:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/herdrdev/herdr\" target=\"_blank\" rel=\"noopener\">Herdr</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/herdrdev/herdr/tree/18061191fdc019498610aee81f0df93f6c2ebd31\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 18061191fdc019498610aee81f0df93f6c2ebd31\">1806119 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: A. Herdr&#39;s supported standard mode hosts autonomous coding agents that execute domain work, and its first-party skill lets an agent create and drive those persistent worker sessions. The operational decision/action loop is therefore present rather than merely constructible.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: —. Herdr supplies agent/session status, prompt, wait and resume primitives, but the reviewed pin does not identify a concrete inter-S1 collision, oscillation or dependency disturbance that a specific Herdr mechanism regulates and closes into changed later S1 behavior. Generic transport and synchronization are insufficient under the current S2 test.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: —. Session lifecycle and per-agent state do not establish a whole-organization current view plus authority over shared resources, commitments, priorities or constraints.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. No materially independent complementary audit channel with corrective closure was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. No outside-looking prospective organizational adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Purpose and ultimate policy remain external to the runtime.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9b431dfc4e818567d073e9a545bf346497b4addd/assessments/herdr.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9b431dfc4e818567d073e9a545bf346497b4addd\">9b431df &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-19T16:02:41+03:00\"><th scope=\"row\"><a href=\"https://github.com/wedow/harness\" target=\"_blank\" rel=\"noopener\">wedow Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-19\">2026-10-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/wedow/harness/tree/5f5d968a86b9762f4c69a6e4d0fe3bf1c5cb5c44\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5f5d968a86b9762f4c69a6e4d0fe3bf1c5cb5c44\">5f5d968 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Select and execute context-sensitive tools or final answers for an operator-specified software/workspace task. - Disturbance / variety regulated: Unpredictable repository files, tool outputs/errors, user task constraints and successive observations from tool actions. - Decisive decision or feedback right: A configured model returns tool-call names and inputs or a final response; the first-party receive hook creates the next toolexec step, which executes and returns actual results for later model decisions. - Decision owner: Model-backed agent operating through shipped provider hooks and tool executors; a provider supplies cognition, but tool choice is genuinely wired into the first-party agent cell rather than a developer-only example. - Supporting / enforcement mechanisms: Deterministic Bash state follower, tool discovery and --exec dispatch, provider adapters, session messages, error hooks, command controls, transport and session persistence. - Closure path: User goal + saved context → assembled provider messages → model tool selection → executable tool with arguments → saved result → next assembled model turn or final answer. - Boundary reachability: The published hs &quot;task&quot; / bin/harness agent route sources bundled plugins/core, resolves the provider and invokes agentloop. Bundled receive/tool-exec hooks implement the substantive model-to-tool-return path in the normal distribution, subject to valid provider credentials. - Why this is / is not agent-owned: Removing the model leaves a hook pipeline incapable of choosing a substantive next tool on unfamiliar task observations; the deterministic follower and tool executors alone cannot replace that discretionary decision. - Evidence: README.md, bin/harness, plugins/core/commands/agent, plugins/core/hooks.d/send/10-send, plugins/openai/hooks.d/receive/10-save, plugins/core/hooks.d/toolexec/10-exec, plugins/core/hooks.d/tooldone/10-save. - Basis: Explicit shipped source control/feedback path and documented headless command. - Confidence: High for supported model-backed structural capability, not a measured production task-completion claim. - Caveats: Authentication and provider availability required; source inspection does not attest model inference, real task success or external service behavior.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No established separately accountable regulation of actual inter-S1 conflict/oscillation among distinct independently viable operating units. - Disturbance / variety regulated: Child tasks can share provider request capacity and workspace context. A configured semaphore bounds simultaneous provider calls, but no conflict-specific cross-task judgement or feedback stabilizing competing S1 operational policies is demonstrated. - Decisive decision or feedback right: A parent model chooses to spawn a child; nested child inference acquires a mechanical maximum-concurrency slot. No other distinct agent selects a coordination compromise when contention is observed. - Decision owner: Parent model for task decomposition; configured semaphore and depth gate are deterministic supporting restrictions. - Supporting / enforcement mechanisms: HARNESSAGENTCONCURRENCY session-root slot directories, child timeout, HARNESSDEPTH cap, tool-dispatch queue and source discovery. - Closure path: Parent tool request → child subprocess → child output/timeout → parent result; a provider request may wait on a slot. This is task delegation and fixed resource admission, not source-established specific inter-S1 disturbance → regulator decision → adjusted participating-unit behavior. - Why this is / is not agent-owned: A model may choose which child task to ask for, but that S1 task choice does not amount to governance of mutual interference between viable operational units; queue/concurrency enforcement is not its own autonomous S2 right. - Evidence: plugins/subagents/tools/agent, plugins/subagents/tools/agent, plugins/core/hooks.d/send/10-send, plugins/core/hooks.d/send/10-send, plugins/core/hooks.d/toolexec/10-exec. - Basis: Bounded absence after tracing default first-party delegation and configured shared-slot enforcement. - Confidence: Medium-high for declared one-agent/child-task recursion. - Caveats: A custom plugin organization may add S2, but it is not inherited into this frozen default distribution.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No evidenced whole-current organizational management function that owns live priorities, shared commitments and corrective resource decisions over distinct S1 operations. - Disturbance / variety regulated: Provider errors, concurrent inference slots, tool timeouts, task progress and per-session compaction are local execution conditions rather than a complete organizational current-control portfolio. - Decisive decision or feedback right: The operator sets task/provider/concurrency choices; script loops enforce them; no standing first-party agent executive judges whole-system current resource/priority conflicts and returns binding choices. - Decision owner: Operator configuration and task-local model, not a separate S3 executive. - Supporting / enforcement mechanisms: Session directory state, plugin errors, configured limits, hook resolution, child depth gate and optional compaction. - Closure path: Error or slot pressure → deterministic task/transport handling or a return to the same local S1; no whole-current management decision → changed cross-unit operation loop. - Why this is / is not agent-owned: The task model decides immediate work tools but lacks an evidenced whole-current organizational mandate; slot allocator follows predefined limits without decision discretion. - Evidence: bin/harness, plugins/core/hooks.d/send/10-send, plugins/core/hooks.d/error/10-display, plugins/rlm/hooks.d/assemble/25-compact. - Basis: Source-bounded absence of distinct inside-and-now management ownership/closure. - Confidence: Medium-high. - Caveats: A user&#39;s management of multiple terminals or outside host is not counted as first-party S3 parent governance.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No separate complementary operational-reality auditor with independently sourced evidence, corrective judgment and returned revision of operations/S3. - Disturbance / variety regulated: Tool errors, malformed provider output and local context loss can be caught by transport checks; such checks do not independently verify claims made by a current-control executive. - Decisive decision or feedback right: Hooks parse provider/tool results and produce errors; no separately authorized reviewer challenges an operational report and sends corrective findings into governance. - Decision owner: Deterministic error handlers and task agent for subsequent local recovery. - Supporting / enforcement mechanisms: JSON validation, explicit tool-error flags, session transcripts, stderr and stream output, child JSON-schema completeness checks. - Closure path: Tool/provider failure → recorded error/retry/repair by local task agent, rather than complementary S3 reports → independent discrepancy judgment → binding corrective return. - Why this is / is not agent-owned: Persisted logs and schema checking are not an independently reasoning S3 evaluator; spawning an optional subagent does not automatically give it independent audit authority. - Evidence: plugins/core/hooks.d/toolexec/10-exec, plugins/core/hooks.d/error/10-display, plugins/subagents/tools/agent, plugins/openai/hooks.d/receive/10-save. - Basis: Negative from specific shipped verification/log/delegation paths. - Confidence: Medium-high. - Caveats: An external audit workflow or custom configured specialist could require a separate assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No first-party externally prospective scan → new organizational capability option → adoption/return loop is established in the supported default distribution. - Disturbance / variety regulated: Changing task context and available tools can require adaptation; hook discovery each iteration and context compaction are present-task extension/recovery, not future organization strategy. - Decisive decision or feedback right: Operator/file installation chooses plugins; the state follower discovers them. No agent S4 owner selects external opportunities, weighs future options and installs a new operating policy with a return path to later work. - Decision owner: Human/project plugin authors for extensions; task agent for current work/tool choice. - Supporting / enforcement mechanisms: Hot source discovery, extend-harness skill, plugins/rlm compaction and stored session history. - Closure path: User installs/edits plugin → next hook scan sees it, or current context compacts → same task continues; no first-party S4–S3 future-option selection and authorized adoption feedback is evidenced. - Why this is / is not agent-owned: Dynamic plugins and model-authored code could support external development, but this does not establish an agent-owned future organizational strategy decision in the shipped runtime. - Evidence: bin/harness, bin/harness, plugins/core/skills/extend-harness/SKILL.md, plugins/rlm/hooks.d/assemble/25-compact. - Basis: Bounded negative after checking relevant supplied extension and memory paths. - Confidence: Medium-high in documented first-party modes. - Caveats: This does not rule out external human evolution of the open-source project.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party legitimate arbitration of ultimate harness purpose, organizational identity and foundational policy with binding return into operating mode. - Disturbance / variety regulated: User requests, tool access, provider selection and generic action warnings restrict current tasks but do not create an ultimate-purpose constitutional issue. - Decisive decision or feedback right: Users/configuration set prompt, runtime provider, plugins and environmental permissions; default prompts can constrain model calls. No S5 actor judges conflicting organizational identities/ultimate policy and returns a legitimized decision. - Decision owner: External operator/project maintainers for overall aims and constraints; not a packaged first-party S5 mode. - Supporting / enforcement mechanisms: Static system/agent prompt, user configuration, tool wrappers and optional plugin override priority. - Closure path: Operator-configured prompt/tools → model task execution; no institutional identity dispute → legitimate parent/agent decision → changed enduring organizational constitution/operation. - Why this is / is not agent-owned: User-level task instructions and fixed hooks are not the authority to define an organization&#39;s ultimate ends; a model&#39;s tool choice does not confer that right. - Evidence: plugins/core/prompts/001-system.md, plugins/core/hooks.d/assemble/30-prompts, bin/harness, plugins/core/commands/agent. - Basis: Source-bounded negative under released harness distribution. - Confidence: Medium-high. - Caveats: Hosting organization and human plugin governance remain external to this assessment recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/5030085a569e21697e9c066ce13e984f000eda22/assessments/we/wedow-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 5030085a569e21697e9c066ce13e984f000eda22\">5030085 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-26T21:59:57Z\"><th scope=\"row\"><a href=\"https://github.com/boundflow/boundflow\" target=\"_blank\" rel=\"noopener\">BoundFlow</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-27\">2026-09-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/boundflow/boundflow/tree/15c0b20a3a98d3413956cab7fba2fd77c1fa32e2\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 15c0b20a3a98d3413956cab7fba2fd77c1fa32e2\">15c0b20 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform the substantive model-driven work of a configured workflow operation by choosing and executing task-relevant tool actions, interpreting observations and deciding when the agent step is complete. - Disturbance / variety regulated: open-ended task inputs; model/tool choice within the configured agent definition; changing tool results and failures; uncertain intermediate state; bounded cost/token/call/tool budgets; external service responses; incomplete information requiring another action. - Decisive decision or feedback right: choose the next task-specific tool/action and arguments from current model context and returned observations, then decide whether to continue or submit the operation result. - Decision owner: the model-driven first-party BoundFlow Orchestrator path instantiated by OperationContext.runagent(). - Supporting / enforcement mechanisms: BoundFlowWorker; AgentDefinition; provider adapter; AgentGovernor; runtime-policy caps; tool registry/callback dispatch; operation context; traces; durable workflow/request state and backend job dispatch. - Closure path: workflow operation/context -&gt; runagent() resolves policy and calls Orchestrator.runstep() -&gt; model chooses tool call -&gt; first-party callback executes -&gt; tool result returns into message history -&gt; next model call changes action or calls submitresult -&gt; operation receives StepResult and workflow progresses. - Boundary reachability: the README quick-start directly constructs a first-party BoundFlowWorker, registers a workflow, calls ctx.runagent(AgentDefinition(...)) and invokes that workflow through the shipped control plane; the credited loop requires no adjacent benchmark or development-only actor. - Why this is / is not agent-owned: deterministic code supplies policy, transport, callbacks and limits, but it does not choose the contextual task action. Removing the model decision path while retaining those mechanisms would not produce materially the same next-tool/argument/completion decisions. - Evidence: README.md; sdk/python/boundflow/worker.py; sdk/python/boundflow/llm.py. - Basis: explicit + structural. - Confidence: high. - Caveats: workflow handlers and tool callbacks are operator/developer supplied, and external providers supply inference. The autonomy claim is specifically the contextual operational decision loop first-party BoundFlow drives over those configured capabilities.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no qualifying inter-S1 coordination function is established in the generic standard distribution at the assessed workflow recursion. - Disturbance / variety regulated: workflows can contain several operations/agent definitions and the scheduler can queue many runs, but no specific first-party inter-S1 conflict, oscillation or mutual-interference problem is established merely by this plurality. - Decisive decision or feedback right: none established for S2. - Decision owner: none established. - Supporting / enforcement mechanisms: workflow sequencing through Next; shared context; scheduler queues/leases; operation dispatch; approval/input parking; model/tool routing. - Closure path: no material distinct-S1 disturbance -&gt; S2-specific attenuation decision -&gt; changed subsequent behaviour of the affected S1 units is supplied by the generic runtime. - Why this is / is not agent-owned: sequencing, durable state and dispatch coordinate software execution in the ordinary sense, but the Profile requires concrete regulation of interference among distinct operational units rather than generic orchestration primitives. - Evidence: docs/concepts.md; sdk/python/boundflow/worker.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: an application built with BoundFlow may instantiate several independently accountable operations and implement its own coordination logic; that downstream organization would require its own system-in-focus assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: regulate the current operating posture of the managed workflow as a whole by applying parent-authored resource/model constraints and workflow intervention policy from aggregated operational evidence. - Disturbance / variety regulated: excessive cost/LLM/tool use; repeated failures; excessive latency; approval rejections; tool failure accumulation; degraded workflow version behaviour; need to pause/cool down/roll back or narrow an agent&#39;s effective operating envelope. - Decisive decision or feedback right: define which whole-workflow/agent metric conditions warrant a current-control intervention and what intervention follows — including effective model/resource caps and workflow pause/cooldown/version rollback. - Decision owner: the legitimate self-hosted operator/parent that authors RuntimePolicy, AgentRule and WorkflowRule thresholds/actions/targets. BoundFlow&#39;s governor and lifecycle engines enforce/evaluate those selected policies but do not autonomously choose the organizational objective, threshold or target action. - Supporting / enforcement mechanisms: per-run metric collection; invocation history; workflow version metrics; AgentGovernor; applylifecyclerules(); backend LifecyclePolicyEngine.ResolvePolicy(); scheduler; workflow lifecycle state; durable audit records; policy snapshots and worker-side enforcement. - Closure path: operations emit cost/call/failure/latency/tool/approval evidence -&gt; BoundFlow stores rolling/version metrics -&gt; the configured lifecycle rule is evaluated -&gt; the parent-selected action changes effective model/caps or workflow state/version -&gt; scheduler/worker subsequent execution uses that returned current-control state. - Boundary reachability: the documented self-hosted SDK/control-plane API directly exposes setagentruntimepolicy, setagentlifecyclepolicy and setworkflowlifecyclepolicy; the backend/worker standard distribution evaluates and enforces those policies in ordinary workflow execution. - Why this is / is not agent-owned: the runtime has hard authority to block, meter, pause, cool down and change versions, but Methodology 0.3.6 separates enforcement from decision ownership. Counterfactually removing the operator-selected rule while leaving the deterministic evaluator in place removes the reason/action choice; the evaluator cannot independently decide what constitutes unacceptable cost/failure or which target model/version should replace the current one. - Whole-system current view: workflow lifecycle evaluation consumes rolling metrics and version-level totals for the managed workflow, while agent lifecycle evaluation consumes recent per-agent invocation history inside the same managed workflow. The resulting state is applied at the workflow/agent control boundary rather than as one model&#39;s local task observation. - Current-control decision scope: current constraints and intervention over model selection, maximum calls/cost/tokens, tool limits, workflow pause/cooldown and active workflow version. These affect resource use and whether/how the operational workflow may continue. - Evidence: README.md; sdk/python/boundflow/policies.py; sdk/python/boundflow/lifecycle.py; internal/lifecyclepolicy/engine.go; docs/concepts.md. - Basis: explicit + structural. - Confidence: high. - Caveats: this is specifically a parent-governed self-hosted operator mode. A deterministic policy engine is not credited with autonomous S3 ownership, and ordinary per-task human approval is not relied on to establish the whole-system S3 function.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no qualifying complementary and sufficiently independent audit judgment with corrective return is established in the supported runtime. - Disturbance / variety regulated: BoundFlow records governance decisions and detailed run traces, and it monitors cost/failure/tool metrics, but those evidence surfaces primarily report or enforce the same operational/control paths. - Decisive decision or feedback right: no separately situated auditor is shown obtaining materially complementary access to operational reality, issuing an independent audit judgment and returning findings that change subsequent operation. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: server-side governance audit log; operation/agent/LLM/tool traces; OpenTelemetry sinks; policy metric counters; approval audit; deterministic lifecycle evaluation; tests. - Closure path: operational/control decisions -&gt; audit/trace records and metrics; policy evaluation can act on the same recorded operational metrics, but there is no independent audit judgment -&gt; corrective finding -&gt; changed operation loop. - Why this is / is not agent-owned: logging a policy action or trace, validating limits, or reusing ordinary run metrics for lifecycle control does not create complementary audit independence. - Evidence: README.md; docs/concepts.md; sdk/python/boundflow/worker.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: a downstream application could attach an independent reviewer/auditor through tools/workflow code, but generic extensibility does not establish first-party S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no qualifying external-and-prospective intelligence loop that develops and adopts future capability/posture from environmental distinctions is established in the standard runtime. - Disturbance / variety regulated: prior-run cost/failure/latency/tool/approval metrics can change later operating constraints or active workflow version, but these are inside-and-now operational/control signals rather than an external prospective intelligence process. - Decisive decision or feedback right: no first-party actor is shown sensing external/future-relevant change, generating alternative capability/strategy options and selecting an adaptation that returns into present capability. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: agent/workflow lifecycle metrics; model switching; version rollback; durable history; operator-updated workflow versions/configuration; external integration support. - Closure path: prior internal run metrics -&gt; configured lifecycle rule -&gt; current model/cap/version control is S3 parent governance; no external distinction -&gt; prospective adaptation option -&gt; adopted changed capability loop closes. - Why this is / is not agent-owned: automatic model downgrade or workflow rollback reacts to internal performance under an already-authored rule. It changes current operating posture but does not develop future options from the outside environment. New workflow versions/policies remain developer/operator-authored outside the autonomous runtime. - Evidence: README.md; sdk/python/boundflow/lifecycle.py; internal/lifecyclepolicy/engine.go. - Basis: explicit + structural absence. - Confidence: high. - Caveats: lifecycle adaptation is intentionally not promoted to S4 merely because it affects future runs; the decisive evidence remains internal operational performance under pre-authored current-control rules.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy authority is established at the managed-workflow recursion. - Disturbance / variety regulated: workflow purpose/code, system prompts, tool set, model/provider, runtime/lifecycle policies, version targets, approvals and deployment configuration constrain behavior but are authored by operator/developer/parent rather than decided by a first-party S5 closure. - Decisive decision or feedback right: define or revise the ultimate purpose/identity/top-level normative policy of the BoundFlow-managed organization itself. - Decision owner: external operator/developer/configuration; no qualifying first-party S5 closure is established. - Supporting / enforcement mechanisms: workflow registration/versioning; runtime/lifecycle policy storage and enforcement; API keys/tenant state; approval gates; model/tool configuration; server-side governance audit. - Closure path: top-level purpose/policy is supplied through workflow code/configuration and then enforced; no identity-level issue -&gt; authoritative S5 judgment -&gt; returned top-level policy -&gt; subsequent organization governed by that decision loop closes inside the harness. - Why this is / is not agent-owned: BoundFlow can strongly enforce policy without deciding what the organization ultimately is for or which ultimate policy it should adopt. Generic operator configuration and task approvals are explicitly insufficient S5 evidence. - Evidence: README.md; sdk/python/boundflow/policies.py; docs/concepts.md. - Basis: explicit + structural absence. - Confidence: high. - Caveats: the S3 parent mode records legitimate operator authority over current control; it does not imply that every operator-authored policy is S5.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d7d585a2b49aa6a75e24066e4092cb47e8d36463/assessments/boundflow.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d7d585a2b49aa6a75e24066e4092cb47e8d36463\">d7d585a &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-10T20:25:25+03:00\"><th scope=\"row\"><a href=\"https://github.com/swarm-ai-research/agency-os\" target=\"_blank\" rel=\"noopener\">Agency-OS</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-10\">2026-10-10</time></td><td class=\"review-ref\"><a href=\"https://github.com/swarm-ai-research/agency-os/tree/010d216b10cb6f504de27312de0112dc7782e4ee\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 010d216b10cb6f504de27312de0112dc7782e4ee\">010d216 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform assigned business/coding analysis tasks through first-party instantiated model-driven BusinessAgent work cells and a model-call/response feedback path. - Disturbance / variety regulated: user requests, changing task contexts, model outputs, tool authorization constraints and execution failures. - Decisive decision or feedback right: configured LLM agent chooses substantive task response using its composed spec/system prompt and task context. - Decision owner: BusinessAgent model actor instantiated by Agency-OS&#39;s factory in a running organization, with SWARM LLMAgent substrate bundled as a dependency; remote model inference remains external. - Supporting / enforcement mechanisms: package manifests, agent spec parser, provider config, tenant-auth task queue, TaskWorker, local model invocation, cost/metering and outcome recording. - Closure path: user/CLI/API submits task → organization allocates it to a BusinessAgent → persisted task claimed by worker → agent.executetask passes sanitized task/context to callllmsync → LLM response recorded as task result/trajectory and returned through client polling, permitting further work. - Boundary reachability: TaskWorker.executetask calls BusinessAgent.executetask from a worker consumption loop, and CLI offers direct org.submittask(... execute=True); this is installed runtime, not only benchmarks. - Why this is / is not agent-owned: without a hosted completion model, factory, queue and gates cannot produce discretionary task content, while deleting deterministic bid score calculations does not remove the model-owned task decision. - Evidence: businessagent.py; agentfactory.py; worker.py; tasks.py; organization.py; cli.py - Basis: structural + explicit. - Confidence: high in configured provider-backed mode. - Caveats: the default BusinessAgent implementation is a bounded model-generated response path; code-writing/tool execution or autonomous coding substeps are not presumed from agent identity or unrelated benchmark examples. Provider/SWARM runtime dependencies are explicit.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate competing worker execution of one assigned shared task when multiple queue consumers concurrently observe an available task. - Disturbance / variety regulated: two independently running TaskWorker processes can poll the same assigned task and both attempt an agent model execution, causing duplicated paid work and inconsistent task status/result recording. - Decisive decision or feedback right: only one concurrent consumer may transition the task from assigned to executing; a loser must not execute this task. - Decision owner: first-party SQLAlchemy database conditional-update transaction, not an agent negotiating or a language model deciding task ownership. - Supporting / enforcement mechanisms: tenant/org task ledger, atomic UPDATE tasks SET status=executing WHERE taskid=? AND status=assigned, rowcount result, main worker polling loop and status transition. - Closure path: two TaskWorker participants read the same pending task → both attempt claimtask → DB commits a single successful transition → loser receives False and skips execution → only admitted work cell calls the assigned BusinessAgent; later task result is persisted. - Boundary reachability: both storage.Database.claimtask and TaskWorker.run are shipped runtime paths; API persists assigned tasks for workers. Scaling worker processes is explicitly supported. - Why this is / is not agent-owned: the duplicate-execution collision is resolved by an atomic conditional gate, with no discretionary model choice of which runner receives a contested task. - Distinct S1 units: two separate TaskWorker consumers, each able to instantiate/operate a BusinessAgent for the same organization, as concurrent execution work cells. - Inter-S1 disturbance: duplicate processing of the same shared task would consume tokens/budget twice and race updates to task results, disrupting legitimate execution. - Attenuating coordination relation: SQL conditional status=assigned compare-and-set permits exactly one transition to executing; only successful claimant proceeds to executetask. - Feedback into subsequent S1 behaviour: the failed claimtask boolean prevents the unsuccessful consumer from entering model execution, so execution occurs once and the loser can poll other tasks. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the mechanism addresses an identified cross-worker duplicate execution collision, not selection of the best bidder, task ordering or message passing. - Evidence: storage.py; worker.py; tasks.py; organization.py - Basis: structural + explicit. - Confidence: medium-high for concurrent worker mode. - Caveats: this is narrowly queue-consumer S2; bid auctions are static one-task allocation and not inherently S2. It does not prove distributed file-write conflict resolution, autonomous S2 negotiation, or globally balanced worker fairness.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3 / regulation: - State: ? - Function: whole-current regulation of organization workload, active commitments and resource priorities rather than local per-task assignment and budget checking. - Disturbance / variety regulated: uneven workloads, failed/frozen business agents and conflicts between active projects. - Decisive decision or feedback right: per-task highest-bid selection and circuit-breaker gating are real but do not establish an owner deciding global current priorities/resource reallocations across the operating organization. - Decision owner: configurable package/organization owner and deterministic bid sort / freeze-threshold code; no distinct whole-current S3 agent/controller established. - Supporting / enforcement mechanisms: roster, task history, bid score, wallet and trust, model-call runtime, governance controls and owner APIs. - Closure path: task arrives → algorithm picks one eligible agent → result recorded, but no demonstrated whole-current multi-task visibility → regulation decision → changed commitments across S1 units. - Boundary reachability: auction and governance are first-party operational paths but fail the function-specific aggregate current-control criterion on current evidence. - Why this is / is not agent-owned: a model executing one task or deterministic ranking individual bid scores does not own current management of the whole organization&#39;s portfolio. - Whole-system current view: live agent roster and per-task history are stored, but no bound whole-current priority/commitment decision loop is evidenced. - Current-control decision scope: winner selection for isolated tasks and failure gating, not global allocation governance. - Evidence: organization.py; taskrouter.py; businessagent.py; worker.py; governance.py - Basis: structural + unresolved. - Confidence: medium in incomplete mapping. - Caveats: do not infer S3=A from the organization label or S3=P from any individual manager approval header.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: challenge normal agent work claims through independent evidence access and return corrections. - Disturbance / variety regulated: an agent reporting an output that fails requested tests or violates constraints. - Decisive decision or feedback right: the optional review-workflow engine accepts caller-supplied evidence and approval counts; no guaranteed independently appointed reviewer with direct evidence and consequent correction loop is demonstrated in the shipped task-worker path. - Decision owner: unknown; optional QA feedback can be passed into a helper but that helper is not automatically installed as an independent auditor. - Supporting / enforcement mechanisms: WorkflowEngine minimum evidence/approval gates, FeedbackLoop helper, trajectory capture, trust/circuit breakers and audit event records. - Closure path: a caller may set supplied approvals and evidence, and QA helper can output rework; no proven separate reviewer acquires raw evidence and returns a corrective instruction to the original executing agent through first-party live task worker. - Boundary reachability: quality-gate helper and QA feedback class ship, but first-party runtime review execution and authority separation are not bound to the standard task pathway. - Why this is / is not agent-owned: static evidence count and approval threshold do not constitute independent substantive audit judgment; benchmark auditors cannot be borrowed as deployed product audit actors. - Claim being audited: the winning model agent completed an assigned task correctly. - Ordinary reporting path: BusinessAgent result, task status and trajectory. - Complementary access path: possible QA reviewer inspecting implementation/source outside worker claim, not shown as mandatory enacted workflow. - Independence boundary: no independently instantiated reviewer plus direct artifact access established for this assessed operating mode. - Who acts on findings: hypothetical coordinator or human; demonstrated feedback-to-original-worker closure absent. - Evidence: workflowengine.py; feedbackloops.py; worker.py; trajectory.py; pipeline.py - Basis: structural + unresolved. - Confidence: medium in insufficient evidence. - Caveats: S3 unknown, not absent; review/gate architecture is not enough for positive ownership.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: prospectively sense changes in the organization environment and develop future capability adaptation options. - Disturbance / variety regulated: changing customer objectives and model/provider conditions. - Decisive decision or feedback right: no first-party prospective environmental option-generation/selection/returned adaptation right established. - Decision owner: unresolved. - Supporting / enforcement mechanisms: trust/reputation scores, historical task success and failure, cost-aware task bids, memory decay and optional planning components. - Closure path: task outcomes alter agent reputation and later bid scoring, but that is performance feedback for reactive per-task selection, not an independently evidenced outside-and-then prospecting/adaptation function. - Boundary reachability: reputation and task selection are live; that is insufficient for S4. - Why this is / is not agent-owned: static trust rules affecting future bids do not show a model/legitimate parent choosing new future organization capabilities. - External distinction: no specific outside horizon monitoring path established. - Future / prospective distinction: past outcome statistics influence subsequent route quality but are not necessarily prospective intelligence. - Adaptation option generated: unverified. - Path back into current capability / S3: no separate S4 adaptation decision and change authority. - Evidence: organization.py; businessagent.py; trust.py; executor.py; decay.py - Basis: structural + unresolved. - Confidence: medium in insufficiency. - Caveats: this does not deny that a suitably configured research organization could have S4 at another recursion.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S5 / identity: - State: ? - Function: ultimate purpose and legitimate policy identity of the whole organization when fundamental authority conflicts arise. - Disturbance / variety regulated: changes to organizational mission and legitimate authority rather than per-task tool access. - Decisive decision or feedback right: human defines agent roles, wallets, governance preset, charters, tool denies and high-impact approval; no distinct ultimate-policy-level dispute and authoritative return is reconstructed. - Decision owner: configuring operator/tenant for ordinary policy, no proven S5 identity decision owner. - Supporting / enforcement mechanisms: package YAML, governance preset, permission checker, budget and circuit-breaker policy, task approval headers and API auth. - Closure path: configuration and manager approval affect task admission, but do not show identity/purpose change proposal → legitimate parent decision → returned governance for future operations. - Boundary reachability: governance parameters are shipped, but not automatically S5. - Why this is / is not agent-owned: budget/permissions enforcement and labels such as governance are not the constitutive policy decision itself. - Identity / ultimate-policy issue: no concrete policy identity conflict with closure found. - Ultimate authority in each claimed mode: no positive S5 autonomous or parent mode claimed. - Return-to-operation path: per-task permission choices returned; no identity-level closure evidenced. - Evidence: README.md; schema.py; presets.py; tasks.py; governance.py - Basis: structural + unresolved. - Confidence: medium in insufficient evidence. - Caveats: human approval of a high-impact task is a local permission gate, not a demonstrated identity-level S5 process.\">?</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/87194b5cf755cb4dc882d0e903099a1cd5edb7a6/assessments/agency-os.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 87194b5cf755cb4dc882d0e903099a1cd5edb7a6\">87194b5 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-06T18:32:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/robkaandorp/SharpCoder\" target=\"_blank\" rel=\"noopener\">SharpCoder</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-06\">2026-10-06</time></td><td class=\"review-ref\"><a href=\"https://github.com/robkaandorp/SharpCoder/tree/f35e4003b41020204897aa8f6da3ba9bc1cdf590\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f35e4003b41020204897aa8f6da3ba9bc1cdf590\">f35e400 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously inspect, modify and verify software in response to a coding objective, directly or through bounded delegated sub-sessions. - Disturbance / variety regulated: unfamiliar code, implementation choices, test/tool outcomes, context overflow, provider/model behavior and delegated analysis/research tasks. - Decisive decision or feedback right: choose substantive coding/tool actions, interpret returned evidence, decide when delegation is useful and decide when the requested operational outcome is complete. - Decision owner: the active model-backed SharpCoder coding agent; configured child model sessions own decisions inside their bounded delegated tasks. - Supporting / enforcement mechanisms: built-in tools, path-safety/tool capability configuration, session persistence/forking, context compaction, subagent concurrency/timeouts and provider wrappers. - Closure path: caller request → model selects repository/tool action or bounded subagent → first-party runtime executes and returns tool evidence or child summary → model revises work → model completes the request. - Boundary reachability: the normal public \\CodingAgent.ExecuteAsync\\ / streaming paths instantiate the model/tool loop, and configured subagent tools are injected into that same shipped execution path. - Why this is / is not agent-owned: deterministic runtime code transports and constrains actions, but removing the model actors removes the open-ended implementation/investigation/completion judgments. - Evidence: README.md; src/SharpCoder/CodingAgent.cs; src/SharpCoder/SubAgents/SubAgentManager.cs. - Basis: explicit + structural. - Confidence: high. - Caveats: subagents are optional and read-only by default; the core positive S1 claim does not depend on enabling them.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party inter-S1 coordination loop is established. - Disturbance / variety regulated: configured write-enabled children could contend in one workspace, but the reviewed runtime does not place such peer interference under a function-specific attenuation/feedback relation. - Decisive decision or feedback right: none established for S2. - Decision owner: none established. - Supporting / enforcement mechanisms: \\MaxConcurrentSubAgents\\ semaphore, child capability ceilings, per-run immutable option snapshots and result/status collection bound concurrency and capability but do not coordinate concrete peer conflicts. - Closure path: not applicable. - Boundary reachability: no positive S2 path claimed. - Why this is / is not agent-owned: the main agent may decide to start multiple tasks, while the runtime limits how many run; neither path supplies a concrete collision detector/reservation/worktree/negotiation loop that feeds mutual adjustment back into peer S1 behavior. - Evidence: README.md; src/SharpCoder/SubAgents/SubAgentManager.cs; src/SharpCoder/SubAgents/SubAgentOptions.cs. - Basis: structural absence review. - Confidence: high. - Caveats: serialization by a concurrency semaphore is generic load control, not evidence that an actual inter-S1 interference mode is being attenuated.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party whole-system current-control loop is established over the active child set. - Disturbance / variety regulated: child status, timeout and completion are observable, but no actor is shown owning substantive live reallocation/intervention over the whole current set of commitments. - Decisive decision or feedback right: none established for S3. - Decision owner: none established. - Supporting / enforcement mechanisms: \\startsubagent\\, \\awaitsubagents\\, \\getsubagentstatus\\, lifecycle events, timeout state and host-visible \\ActiveSubAgentManager\\. - Closure path: not applicable. - Boundary reachability: no positive S3 path claimed. - Why this is / is not agent-owned: the main model can create work, poll it and await summaries, but the shipped model toolset has no selective live cancel/retry/reprioritize/reallocate operation over already-running children. \\DisposeAsync\\ cancels all children as shutdown, and caller-token cancellation explicitly leaves running children alive. - Evidence: src/SharpCoder/SubAgents/SubAgentTools.cs; src/SharpCoder/SubAgents/SubAgentManager.cs; src/SharpCoder/CodingAgent.cs. - Basis: structural absence review. - Confidence: high. - Caveats: lifecycle visibility and stop-all disposal are useful controls but do not satisfy the Methodology 0.3.6 whole-current view + substantive current-control decision threshold.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material independent complementary audit path is established. - Disturbance / variety regulated: no dedicated independent reviewer/verifier is wired to challenge an implementation claim and return findings into corrective operation. - Decisive decision or feedback right: none established for S3. - Decision owner: none established. - Supporting / enforcement mechanisms: generic subagents, normal test/tool execution, session forks and a separate compaction model may provide additional computation but are not function-specific independent audit constructors. - Closure path: not applicable. - Boundary reachability: no positive S3 path claimed. - Why this is / is not agent-owned: any child can be asked ad hoc to review, but the shipped runtime provides only generic task delegation; it does not establish an authorship-independent reviewer role, complementary evidence path and corrective verdict loop. - Evidence: README.md; src/SharpCoder/SubAgents/SubAgentTools.cs; src/SharpCoder/AgentSession.cs. - Basis: structural absence review. - Confidence: high. - Caveats: generic user/model-authored review prompts remain S1 composition unless the distribution supplies the distinct audit relation itself.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective adaptation loop is established. - Disturbance / variety regulated: no external/future distinction is transformed into organizational adaptation options and returned into present capability. - Decisive decision or feedback right: none established for S4. - Decision owner: none established. - Supporting / enforcement mechanisms: persistent sessions, session forking, context compaction, skills and model configuration preserve/reduce context or supply current capabilities but do not close S4. - Closure path: not applicable. - Boundary reachability: no positive S4 path claimed. - Why this is / is not agent-owned: a compaction model summarizes past conversation for current continuity, and persisted sessions can be resumed later, but neither mechanism develops prospective adaptation options from changing external conditions. - Evidence: src/SharpCoder/ContextCompactor.cs; src/SharpCoder/AgentSession.cs; README.md. - Basis: structural absence review. - Confidence: high. - Caveats: persistence and context summarization can improve future turns, but memory reuse/compression is not sufficient S4 under the active Profile.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy governance loop is established. - Disturbance / variety regulated: no identity-level policy conflict is routed to an authoritative S5 owner and returned as governing policy. - Decisive decision or feedback right: none established for S5. - Decision owner: none established. - Supporting / enforcement mechanisms: \\AgentOptions\\, tool/capability flags, path safety and host-supplied system/custom instructions constrain execution but do not create identity governance. - Closure path: not applicable. - Boundary reachability: no positive S5 path claimed. - Why this is / is not agent-owned: the coding agent operates within host/developer-provided policy and capability settings and cannot authoritatively redefine SharpCoder&#39;s identity or ultimate operating principles. - Evidence: README.md; src/SharpCoder/AgentOptions.cs; src/SharpCoder/CodingAgent.cs. - Basis: structural absence review. - Confidence: high. - Caveats: callers legitimately configure policy/capability constraints, but generic host configuration is not an identity/ultimate-policy decision loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9d8dacc64c450daf454f1555da23de7601d5f554/assessments/sharpcoder.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9d8dacc64c450daf454f1555da23de7601d5f554\">9d8dacc &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-05T03:54:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/robertnathe/AutonomousCodingAgent\" target=\"_blank\" rel=\"noopener\">AutonomousCodingAgent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-05\">2026-10-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/robertnathe/AutonomousCodingAgent/tree/5054511c80659281747e2d2530b772bed0ca8b18\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5054511c80659281747e2d2530b772bed0ca8b18\">5054511 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: produce working code and requested artifacts through autonomous planning, tool use, execution, debugging and validation-driven iteration. - Disturbance / variety regulated: unfamiliar task requirements, codebase/file state, syntax/compile/runtime errors, missing dependencies, model-provider failures, validation mismatches and remembered prior outcomes. - Decisive decision or feedback right: select or repair a plan, choose next coding/tool actions from observations and hints, revise failed work, and continue until validated completion or bounded failure. - Decision owner: the model-backed CodingAgent. - Supporting / enforcement mechanisms: planner/decomposer, tool parser/executor, syntax checks, code executor, backend fallback/rate limits, progress/validation hints, semantic/failure memory and optional Docker limits. - Closure path: task/context → agent plan/action choice → tool/code execution → concrete observation/validation feedback → evidence returns to the agent → revised action until validator-confirmed success or bounded stop. - Boundary reachability: interactive single-task mode directly invokes CodingAgent.run; the frozen repository contains the complete model/tool/validation composition. - Why this is / is not agent-owned: removing the model-backed actor leaves deterministic executors, validators and memory storage but removes the open-ended decisions that turn task/evidence into code actions. - Evidence: README; AdvancedCodingAgent.py (CodingAgent, ToolExecutor, CodeExecutor, planners/backend manager); safe-runner scripts. - Basis: explicit + structural. - Confidence: high. - Caveats: deterministic validation owns acceptance checks, not the open-ended coding decisions themselves.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct coordination function among multiple S1 operational units is established. - Disturbance / variety regulated: planning, decomposition, tool batches and memory retrieval organize one coding actor&#39;s work; they do not expose peer S1 units whose mutual interference or oscillation is regulated. - Decisive decision or feedback right: no S2-specific choice over inter-S1 conflict or mutual adjustment was found. - Decision owner: not established at S2 level. - Supporting / enforcement mechanisms: task decomposition, dependency planning, action sequencing, file backup and deterministic validation. - Closure path: these mechanisms change the single actor&#39;s execution order and retries, not a peer-coordination relation. - Why this is / is not agent-owned: decomposition into sub-goals is not evidence of distinct operational units or coordination among them. - Evidence: README; AdvancedCodingAgent.py. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: none material at the frozen boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function over a standing set of operations is established. - Disturbance / variety regulated: progress checklists, validation requirements, retry limits, provider fallback and execution timeouts regulate one focal coding task. - Decisive decision or feedback right: no separate authority manages a portfolio of current S1 commitments/resources/priorities on behalf of the whole. - Decision owner: not established at S3 level. - Supporting / enforcement mechanisms: validation loop, max turns/actions, timeouts, backend cooldowns, expected-output tracking and abort flag. - Closure path: current-task evidence returns directly to the same S1 actor; no separate whole-current management loop is present. - Why this is / is not agent-owned: planning and retry decisions are S1 task regulation; deterministic limits/validation are enforcement, not S3 ownership. - Evidence: AdvancedCodingAgent.py; README. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: none material at the frozen boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no sufficiently independent complementary audit path is established. - Disturbance / variety regulated: deterministic syntax/execution/expected-output validation challenges generated code, but it is a mandatory in-band acceptance mechanism inside the same coding loop. - Decisive decision or feedback right: no separate auditor exercises an independent claim-checking judgment beyond the ordinary production validation path. - Decision owner: not established at S3 level. - Supporting / enforcement mechanisms: validator, checkearlysuccess, direct execution checks, syntax validation, expected-output checks and benchmark tests. - Closure path: validator results feed directly back to the same coding actor as ordinary operational feedback; the adjacent TestSuite is user-invoked evaluation, not a complementary control path in single-task operation. - Why this is / is not agent-owned: self-validation and deterministic checks inside the producer loop lack the complementary independence required for S3. - Evidence: README; AdvancedCodingAgent.py validation and TestSuite paths. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: the benchmark suite can test the product, but repository co-location does not make it an operational audit owner.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no externally and prospectively oriented adaptation loop is established. - Disturbance / variety regulated: persisted prior successes/failures and retrieval outcomes improve future task execution, while reflection can suggest local capability labels after failures. - Decisive decision or feedback right: no first-party actor models external/future change, develops adaptation options for the harness, and returns a selected adaptation into current capability/S3. - Decision owner: not established at S4 level. - Supporting / enforcement mechanisms: semantic memory, failure patterns/hints, outcome-adjusted retrieval weights/thresholds, cached-plan replay and ReflectionEngine. - Closure path: historical internal task outcomes alter later retrieval/hints/plan reuse; they do not form an outside-and-then conversation about future environmental change and organizational adaptation. - Why this is / is not agent-owned: learning from internal task outcomes, memory consolidation and self-reflection are explicitly insufficient for S4 without external/prospective distinctions and adaptation-option closure. - Evidence: README; SemanticMemoryManager; ReflectionEngine; CodingAgent.run. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: suggestedcapability values are hints placed into current context; the code does not implement or govern the suggested new capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity- or ultimate-policy-level closure is established. - Disturbance / variety regulated: fixed prompts, safety limits, backend priority, execution timeouts, optional Docker resource constraints and user-selected task/test mode constrain operation. - Decisive decision or feedback right: no identity/ultimate-policy issue is routed to a legitimate authority and returned as a durable governing decision. - Decision owner: not established at S5 level. - Supporting / enforcement mechanisms: AgentConfig, system prompt rules, max turns/actions/timeouts, Docker limits and interactive menu. - Closure path: configuration and safety constraints govern ordinary actions but do not close identity-level disputes or policy adaptation. - Why this is / is not agent-owned: static configuration, prompts and resource limits are enforcement constraints, not S5. - Evidence: README; AgentConfig; CodingAgent.systemprompt; safe-runner scripts. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: maintainers/operators can edit code/config outside the run, but that development authority is adjacent to the assessed operating boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/15e1e5562d26c088fd5c5688f7c49af69b013ae4/assessments/autonomouscodingagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 15e1e5562d26c088fd5c5688f7c49af69b013ae4\">15e1e55 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-17T22:55:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/stablyai/orca\" target=\"_blank\" rel=\"noopener\">Orca</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/stablyai/orca/tree/c33a446190bdfa21286a373e097c50a2b3e0a4d4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision c33a446190bdfa21286a373e097c50a2b3e0a4d4\">c33a446 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: A. Orca&#39;s standard distribution launches supported coding agents such as Claude Code and Codex to perform autonomous coding work. Those agent loops are the operational units hosted by the control plane; they are not merely constructor placeholders.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: C. Orca gives concurrent workers isolated Git worktrees specifically so parallel agent changes do not collide in one checkout. That is a concrete structural attenuation of inter-S1 file/workspace interference. The reviewed path does not establish an autonomous agent deciding the coordination relation, so the mechanism remains constructor/runtime-owned.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: —. Session status, wake/signal and remote steering expose operator control over individual runs, while fan-out starts multiple candidates. The pinned evidence does not establish a separate first-party whole-system regulator with current authority over shared organizational priorities, commitments or resources.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. Human diff comparison and annotation are useful review surfaces, but S3 has no parent notation and ordinary human comparison is not a first-party materially independent audit function owned by the harness.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. No outside-looking prospective organizational adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Human accept/merge/steer decisions close task acceptance, not an organizational identity or ultimate-policy tension-and-resolution loop. The historical P therefore does not survive the S5 function test.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9b431dfc4e818567d073e9a545bf346497b4addd/assessments/orca-stablyai.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9b431dfc4e818567d073e9a545bf346497b4addd\">9b431df &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-18T01:17:06+03:00\"><th scope=\"row\"><a href=\"https://github.com/dylanneve1/talon\" target=\"_blank\" rel=\"noopener\">Talon</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/dylanneve1/talon/tree/1a4b8b60e142a6de3e0cdae9c7fa4a34c88b571e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1a4b8b60e142a6de3e0cdae9c7fa4a34c88b571e\">1a4b8b6 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: standard agent sessions/background runs autonomously use tools toward persistent goals.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: per-chat serialization/event bus mechanically prevent execution collisions but do not constitute agent-owned S2 enactment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: task tables, lifecycle state, dispatcher and background scheduling expose current execution state but remain runtime infrastructure; no autonomous whole-system regulator with resource/commitment authority is supplied.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: dreams, logs, task/event views and watcher state do not provide a sufficiently independent complementary audit path that challenges ordinary operational claims.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: self-authored triggers and heartbeats react to external events/conditions, but event reaction alone does not model future environmental change or generate adaptation options coupled to S3. External trigger ≠ S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: persistent goals, soul/personality and configuration can shape behavior, but they are user/configuration authored and do not establish legitimate agent-owned ultimate-policy closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/971ef74afedbf47ef0a54eb5d7c8701453e57f68/assessments/talon.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 971ef74afedbf47ef0a54eb5d7c8701453e57f68\">971ef74 &#8599;</a></td></tr>"];
